IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'dbo.LogonPersonel_audits') AND type in (N'U')) BEGIN CREATE TABLE [dbo].[LogonPersonel_audits]( [Changeid] [bigint] IDENTITY(1,1) NOT NULL, [LogonPersonelId] [bigint] NOT NULL, [Time] [char](5) NOT NULL, [updated_at] [datetime] NOT NULL, PRIMARY KEY CLUSTERED ([Changeid] DESC) WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY] ) ON [PRIMARY] end GO --add guid columm with index IF COL_LENGTH('[dbo].[LogonPersonel_audits]','Guid') IS NULL ALTER TABLE dbo.LogonPersonel_audits ADD [Guid] uniqueidentifier NOT NULL CONSTRAINT DF_LogonPersonel_audits_Guid DEFAULT newId() GO
if not exists (SELECT * FROM sys.indexes WHERE name='ix_LogonPersonel_audits_Guid' AND object_id = OBJECT_ID('[dbo].LogonPersonel_audits')) CREATE UNIQUE INDEX ix_LogonPersonel_audits_Guid ON [dbo].LogonPersonel_audits (Guid) Go --///////////////////////////////////////////////////////////// CREATE or alter TRIGGER trg_LogonPersonel ON LogonPersonel after INSERT,update,delete AS BEGIN SET NOCOUNT ON;
begin INSERT INTO LogonPersonel_audits( LogonPersonelId ,Time ,updated_at ) SELECT i.id ,CONVERT(VARCHAR(5),DateTimeLogM,108) AS Time ,GETDATE() FROM inserted i where ( select top (1) [time] from LogonPersonel_audits where LogonPersonelId =i.ID) is null Or CONVERT(VARCHAR(5),i.DateTimeLogM,108) <> ( select top (1) [time] from LogonPersonel_audits where LogonPersonelId =i.ID) end END

create or Alter Procedure [dbo].[sp_AgreedDeduction_DeleteRow]
	@ID int
As
Begin
    update [dbo].[AgreedDeduction]  
	Set [St] = 0
	Where [ID] = @ID
End
GO
-- ==========================================================================================
create or Alter Procedure [dbo].[sp_AgreedDeduction_Insert]
	@PersonID int,
	@HesabId int,
	@Description [nvarchar](max),
	@DateCreatedM datetime,
	@AmountPayable decimal(18,3),
	@MonthlyInstallment decimal(18,3),
	@AgreedDeductionDetsJson nvarchar(MAX)
As
Begin
	Insert Into AgreedDeduction
		([PersonID],[HesabId],[DateCreatedM],[AmountPayable],[MonthlyInstallment],[AgreedDeductionDetsJson],[Description])
	Values
		(@PersonID, @HesabId, @DateCreatedM, @AmountPayable, @MonthlyInstallment, @AgreedDeductionDetsJson, @Description)

	update person
		set sentToServerStatus = 0
		where id = @PersonID

	Select @@IDENTITY
	Return @@IDENTITY
End
GO
-- ==========================================================================================
create or Alter Procedure [dbo].[sp_AgreedDeduction_SelectAll]
	@personIDs nvarchar(Max),
	@startDate datetime,
    @endDate datetime
As
Begin
	if @personIDs = ''
		SELECT *
		FROM dbo.AgreedDeduction 
		where [St] = 'true'
			and (DateCreatedM between @startDate and @endDate)
		order by [DateCreatedM] desc
	else
		SELECT dbo.AgreedDeduction.*
		FROM dbo.AgreedDeduction INNER JOIN
			 (select item from dbo.SplitStrings(@personIDs,',')) as a on dbo.AgreedDeduction.[PersonID] = cast(a.item as int)
			 where [St] = 1 and (DateCreatedM between @startDate and @endDate)
		order by [DateCreatedM] desc
End

GO
-- ==========================================================================================
