	@AmountPayable decimal(18,3),
	@MonthlyInstallment decimal(18,3),
	@AgreedDeductionDetsJson nvarchar(MAX)
As
Begin
	Update AgreedDeduction
	Set
		[PersonID] = @PersonID,
		[HesabId] = @HesabId,
		[Description] = @Description,
		[DateCreatedM] = @DateCreatedM,
		[AmountPayable] = @AmountPayable,
		[MonthlyInstallment] = @MonthlyInstallment,
		[AgreedDeductionDetsJson] = @AgreedDeductionDetsJson
	Where [ID] = @ID
End
