create or Alter PROCEDURE [dbo].[sp_ATT_TaradodDet_Insert]
	@PersonID int,
	@DateM date,
	@VacationTime int,
	@VacationStart datetime,
	@VacationEnd datetime,
	@VacationDesc nvarchar(max),
	@EKTime int,
	@EKStart datetime,
	@EKEnd datetime,
	@EKDesc nvarchar(max),
	@KKTime int,
	@KKStart datetime,
	@KKEnd datetime,
	@KKDesc nvarchar(max),
	@MissionTime int,
	@MissionStart datetime,
	@MissionEnd datetime,
	@MissionDesc nvarchar(max),
	@FridayTime int,
	@FridayStart datetime,
	@FridayEnd datetime,
	@FridayDesc nvarchar(max),
	@ShiftTime1 int,
	@ShiftStart1 datetime,
	@ShiftEnd1 datetime,
	@ShiftDesc1 nvarchar(max),
	@ShiftTime2 int,
	@ShiftStart2 datetime,
	@ShiftEnd2 datetime,
	@ShiftDesc2 nvarchar(max),
	@ShiftTime3 int,
	@ShiftStart3 datetime,
	@ShiftEnd3 datetime,
	@ShiftDesc3 nvarchar(max),
	@AbsentTime int,
	@AbsendStart datetime,
	@AbsentEnd datetime,
	@AbsentDesc nvarchar(max),
	@NightTime int,
	@NightStart datetime,
	@NightEnd datetime,
	@NightDesc nvarchar(max)
AS
BEGIN
	INSERT INTO dbo.[ATT_TaradodDet]
		([PersonID],[DateM],[VacationTime],[VacationStart],[VacationEnd],[VacationDesc],[EKTime],[EKStart],[EKEnd],[EKDesc],[KKTime],[KKStart],[KKEnd],[KKDesc],[MissionTime],[MissionStart],[MissionEnd],[MissionDesc],[FridayTime],[FridayStart],[FridayEnd],[FridayDesc],[ShiftTime1],[ShiftStart1],[ShiftEnd1],[ShiftDesc1],[ShiftTime2],[ShiftStart2],[ShiftEnd2],[ShiftDesc2],[ShiftTime3],[ShiftStart3],[ShiftEnd3],[ShiftDesc3],[AbsentTime],[AbsendStart],[AbsentEnd],[AbsentDesc],[NightTime],[NightStart],[NightEnd],[NightDesc])
	VALUES
		(@PersonID,@DateM,@VacationTime,@VacationStart,@VacationEnd,@VacationDesc,@EKTime,@EKStart,@EKEnd,@EKDesc,@KKTime,@KKStart,@KKEnd,@KKDesc,@MissionTime,@MissionStart,@MissionEnd,@MissionDesc,@FridayTime,@FridayStart,@FridayEnd,@FridayDesc,@ShiftTime1,@ShiftStart1,@ShiftEnd1,@ShiftDesc1,@ShiftTime2,@ShiftStart2,@ShiftEnd2,@ShiftDesc2,@ShiftTime3,@ShiftStart3,@ShiftEnd3,@ShiftDesc3,@AbsentTime,@AbsendStart,@AbsentEnd,@AbsentDesc,@NightTime,@NightStart,@NightEnd,@NightDesc)
	
	update person
		set sentToServerStatus = 0
		where id = @PersonID

	return @@IDENTITY
END
GO
-- ==========================================================================================
create or Alter PROCEDURE [dbo].[sp_ATT_TaradodDet_Save]
	@PersonID int,
	@DateM date,
	@VacationTime int,
	@VacationStart datetime=null,
	@VacationEnd datetime=null,
	@VacationDesc nvarchar(max),
	@EKTime int,
	@EKStart datetime=null,
	@EKEnd datetime=null,
	@EKDesc nvarchar(max),
	@KKTime int,
	@KKStart datetime=null,
	@KKEnd datetime=null,
	@KKDesc nvarchar(max),
	@MissionTime int,
	@MissionStart datetime=null,
	@MissionEnd datetime=null,
	@MissionDesc nvarchar(max),
	@FridayTime int,
	@FridayStart datetime=null,
	@FridayEnd datetime=null,
	@FridayDesc nvarchar(max),
	@ShiftTime1 int,
	@ShiftStart1 datetime=null,
	@ShiftEnd1 datetime=null,
	@ShiftDesc1 nvarchar(max),
	@ShiftTime2 int,
	@ShiftStart2 datetime=null,
	@ShiftEnd2 datetime=null,
	@ShiftDesc2 nvarchar(max),
	@ShiftTime3 int,
	@ShiftStart3 datetime=null,
	@ShiftEnd3 datetime=null,
	@ShiftDesc3 nvarchar(max),
	@AbsentTime int,
	@AbsendStart datetime=null,
	@AbsentEnd datetime=null,
	@AbsentDesc nvarchar(max),
	@NightTime int,
	@NightStart datetime=null,
	@NightEnd datetime=null,
	@NightDesc nvarchar(max)
AS
BEGIN
	if (exists(Select PersonID from dbo.ATT_TaradodDet where PersonID=@PersonID and DateM=@DateM) )
		EXEC dbo.[sp_ATT_TaradodDet_Update] @PersonID,@DateM,@VacationTime,@VacationStart,@VacationEnd,@VacationDesc,@EKTime,@EKStart,@EKEnd,@EKDesc,@KKTime,@KKStart,@KKEnd,@KKDesc,@MissionTime,@MissionStart,@MissionEnd,@MissionDesc,@FridayTime,@FridayStart,@FridayEnd,@FridayDesc,@ShiftTime1,@ShiftStart1,@ShiftEnd1,@ShiftDesc1,@ShiftTime2,@ShiftStart2,@ShiftEnd2,@ShiftDesc2,@ShiftTime3,@ShiftStart3,@ShiftEnd3,@ShiftDesc3,@AbsentTime,@AbsendStart,@AbsentEnd,@AbsentDesc,@NightTime,@NightStart,@NightEnd,@NightDesc		
	else
		EXEC dbo.[sp_ATT_TaradodDet_Insert] @PersonID,@DateM,@VacationTime,@VacationStart,@VacationEnd,@VacationDesc,@EKTime,@EKStart,@EKEnd,@EKDesc,@KKTime,@KKStart,@KKEnd,@KKDesc,@MissionTime,@MissionStart,@MissionEnd,@MissionDesc,@FridayTime,@FridayStart,@FridayEnd,@FridayDesc,@ShiftTime1,@ShiftStart1,@ShiftEnd1,@ShiftDesc1,@ShiftTime2,@ShiftStart2,@ShiftEnd2,@ShiftDesc2,@ShiftTime3,@ShiftStart3,@ShiftEnd3,@ShiftDesc3,@AbsentTime,@AbsendStart,@AbsentEnd,@AbsentDesc,@NightTime,@NightStart,@NightEnd,@NightDesc
END
GO
