create or Alter PROCEDURE [dbo].[sp_ATT_TaradodDet_Update]
	@PersonID int,
	@DateM date,
	@VacationTime int,
	@VacationStart datetime,
	@VacationEnd datetime,
	@VacationDesc nvarchar(max),
	@EKTime int,
	@EKStart datetime,
	@EKEnd datetime,
	@EKDesc nvarchar(max),
	@KKTime int,
	@KKStart datetime,
	@KKEnd datetime,
	@KKDesc nvarchar(max),
	@MissionTime int,
	@MissionStart datetime,
	@MissionEnd datetime,
	@MissionDesc nvarchar(max),
	@FridayTime int,
	@FridayStart datetime,
	@FridayEnd datetime,
	@FridayDesc nvarchar(max),
	@ShiftTime1 int,
	@ShiftStart1 datetime,
	@ShiftEnd1 datetime,
	@ShiftDesc1 nvarchar(max),
	@ShiftTime2 int,
	@ShiftStart2 datetime,
	@ShiftEnd2 datetime,
	@ShiftDesc2 nvarchar(max),
	@ShiftTime3 int,
	@ShiftStart3 datetime,
	@ShiftEnd3 datetime,
	@ShiftDesc3 nvarchar(max),
	@AbsentTime int,
	@AbsendStart datetime,
	@AbsentEnd datetime,
	@AbsentDesc nvarchar(max),
	@NightTime int,
	@NightStart datetime,
	@NightEnd datetime,
	@NightDesc nvarchar(max)
AS
BEGIN
	Update dbo.[ATT_TaradodDet]
	Set	[VacationTime]=@VacationTime,
	[VacationStart]=@VacationStart,
	[VacationEnd]=@VacationEnd,
	[VacationDesc]=@VacationDesc,
	[EKTime]=@EKTime,
	[EKStart]=@EKStart,
	[EKEnd]=@EKEnd,
	[EKDesc]=@EKDesc,
	[KKTime]=@KKTime,
	[KKStart]=@KKStart,
	[KKEnd]=@KKEnd,
	[KKDesc]=@KKDesc,
	[MissionTime]=@MissionTime,
	[MissionStart]=@MissionStart,
	[MissionEnd]=@MissionEnd,
	[MissionDesc]=@MissionDesc,
	[FridayTime]=@FridayTime,
	[FridayStart]=@FridayStart,
	[FridayEnd]=@FridayEnd,
	[FridayDesc]=@FridayDesc,
	[ShiftTime1]=@ShiftTime1,
	[ShiftStart1]=@ShiftStart1,
	[ShiftEnd1]=@ShiftEnd1,
	[ShiftDesc1]=@ShiftDesc1,
	[ShiftTime2]=@ShiftTime2,
	[ShiftStart2]=@ShiftStart2,
	[ShiftEnd2]=@ShiftEnd2,
	[ShiftDesc2]=@ShiftDesc2,
	[ShiftTime3]=@ShiftTime3,
	[ShiftStart3]=@ShiftStart3,
	[ShiftEnd3]=@ShiftEnd3,
	[ShiftDesc3]=@ShiftDesc3,
	[AbsentTime]=@AbsentTime,
	[AbsendStart]=@AbsendStart,
	[AbsentEnd]=@AbsentEnd,
	[AbsentDesc]=@AbsentDesc,
	[NightTime]=@NightTime,
	[NightStart]=@NightStart,
	[NightEnd]=@NightEnd,
	[NightDesc]=@NightDesc
	Where	[PersonID] = @PersonID and [DateM]=@DateM

	
	update person
		set sentToServerStatus = 0
		where id = @PersonID

END
GO
