create or Alter Procedure [dbo].[sp_BaseYearsSalary_DeleteRow]
	@nYear smallint,
	@GroupId smallint
As
Begin
	Delete [dbo].BaseYearsSalary
	Where [nYear] = @nYear and [GroupId] = @GroupId
End

GO
-- ==========================================================================================
create or Alter Procedure [dbo].[sp_BaseYearsSalary_Save]
	@nYear smallint,
	@GroupId smallint,
	@Price decimal(18,3)
As
Begin
	declare @sw smallint
	select @sw = @GroupId
	from [dbo].[BaseYearsSalary]
	Where [nYear] = @nYear and [GroupId] = @GroupId
	if (isnull(@sw,0)=0)
	begin
		Insert Into [dbo].[BaseYearsSalary]
			( nYear, GroupId, [Price])
		Values
			(@nYear, @GroupId, @Price)
	end
	else
	begin
		Update [dbo].[BaseYearsSalary]
		set [Price] = @Price
		where nYear = @nyear and GroupId = @GroupId
	end
End
GO
-- ==========================================================================================
create or Alter Procedure [dbo].[sp_BaseYearsSalary_SelectAll]
As
Begin
	Select [dbo].[BaseYearsSalary].*, [dbo].[GroupSanavat].[Name]
	From [dbo].[BaseYearsSalary]
	Inner join [dbo].[GroupSanavat]
	on [dbo].[BaseYearsSalary].[GroupId] = [dbo].[GroupSanavat].[ID]
	order by GroupId, nYear asc
End

GO
