	From [dbo].[BaseYearsSalary]
	Inner join [dbo].[GroupSanavat]
	on [dbo].[BaseYearsSalary].[GroupId] = [dbo].[GroupSanavat].[ID]
	Where [nYear] = @nYear and [GroupId] = @GroupId
End

GO
-- ==========================================================================================
create or Alter Procedure [dbo].[sp_BaseYearsSalary_SumPriceSanavat]
	@strYears nvarchar(Max),
	@GroupId smallint
As
Begin
	select Sum(Price) as SumPrice
	from [dbo].[BaseYearsSalary] inner join
	(select item from dbo.SplitStrings(@strYears,',')) as a on [dbo].[BaseYearsSalary].[nYear] = cast (a.item as smallint)
	Where [GroupId] = @GroupId 
End

GO
