	@Code nvarchar(10),
	@Name nvarchar(50),
	@NameKarfarma nvarchar(50),
	@Address nvarchar(100),
	@NerKhBimeh int,
	@NoPeyman nvarchar(10),
	@InsuranceBranch [nvarchar](100),
