create or Alter Procedure [dbo].[sp_EnrollData_Save]
	@PersonId [int],
	@DeviceId [int],
	@EnrollData [varbinary](max)

As
Begin
	Update dbo.EnrollData
		Set EnrollData=@EnrollData
			Where PersonId=@PersonId and DeviceId=@DeviceId

	if @@rowcount = 0
		Insert Into EnrollData
			([PersonId], [DeviceId], [EnrollData])
		Values
			(@PersonId, @DeviceId, @EnrollData)

	Select @@IDENTITY
	Return @@IDENTITY
End
