create or Alter Procedure [dbo].[sp_EventArgsNotify_CountAll]
	@StatusNotify smallint
As
Begin
	declare @recNo int
	set @recNo  = 0
	Select @recNo = COUNT(*) 
		From EventArgsNotify
		where [ST]='true' and (@StatusNotify = 0 or StatusNotify = @StatusNotify )
	
	Select @recNo
	Return @recNo
End
GO
-- ==========================================================================================
create or Alter Procedure [dbo].[sp_EventArgsNotify_DeleteRow]
	@ID smallint
As
Begin
	Delete EventArgsNotify
	Where [ID] = @ID
End

GO
-- ==========================================================================================
create or Alter Procedure [dbo].[sp_EventArgsNotify_Insert]
	@Title nvarchar(500),
	@Message nvarchar(MAX),
	@ObjectId int,
	@NotificationEnum smallint,
	@Secounts smallint,
	@ST bit,
	@DateM [datetime],
	@StatusNotify smallint
As
Begin
	Insert Into EventArgsNotify
			([Title], [Message], [ObjectId], [NotificationEnum], [Secounts], [ST], [StatusNotify], [DateM])
	Values (@Title,   @Message,  @ObjectId,  @NotificationEnum,  @Secounts,  @ST,  @StatusNotify,  @DateM)

	Select @@IDENTITY
	Return @@IDENTITY
End
GO
-- ==========================================================================================
create or Alter Procedure [dbo].[sp_EventArgsNotify_SelectAll]
	@StatusNotify smallint,
	@date1 datetime=null,
	@date2 datetime=null
As
Begin
	if isnull(@date1, '1900-01-01' ) = '1900-01-01'
		Select *
		From EventArgsNotify
		where [ST]='true' and (@StatusNotify = 0 or StatusNotify = @StatusNotify )
	else
		Select *
		From EventArgsNotify
		where [ST]='true' and [DateM] between @date1 and @date2
End
GO
-- ==========================================================================================
create or Alter Procedure [dbo].[sp_EventArgsNotify_SelectRow]
	@ID smallint
As
Begin
	Select *
	From EventArgsNotify
	Where [ID] = @ID
End

GO
