	@KasrMin3 int,
	@KasrPrice decimal(18,3),
	@KasrPrice1 decimal(18,3),
	@KasrPrice2 decimal(18,3),
	@KasrPrice3 decimal(18,3),
	@IsPrint smallint,
	@SumKarkerd decimal(18,3),
	@SumMazaya decimal(18,3),
	@SumKosorat	 decimal(18,3),
	@SumKhales decimal(18,3),
	@CountKarKerd smallint ,
	@CountKarKerdBime smallint ,
	@CountKarKerdMaliat smallint ,
	@CountDays smallint,
	@CountShift smallint,
	@CountMorakhasiWithHoghogh smallint,
	@CountMorakhasiNotHoghogh smallint,
	@CountMorakhasi smallint,
	@CountGheybat smallint,
	@CountNaghes smallint,
	@CountTatil smallint,
	@JsonFishDet [nvarchar](max),
	@MissionPrice decimal(18,3),
	@MissionRoz float,
	@VacationRemind float
As
Begin
	Insert Into Fish
		([PersonID],[FishNO],[DateM],[DateStartM],[DateEndM],[UID],[IDSanad],[Description],[ST],VacationST,EditST,[KarkerdMin],[KarkerdPrice],[EzafeMin],[EzafeMin1],[EzafeMin2],[EzafeMin3],[EzafePrice],[EzafePrice1],[EzafePrice2],[EzafePrice3],[ShabMin],[ShabPrice],[NobatMin1],[NobatPrice1],[NobatMin2],[NobatPrice2],[NobatMin3],[NobatPrice3],[JomeMin],[TatilMin],[Mozafimin],[JarimeRoz],[JomePrice],[TatilPrice],[JarimePrice],[MorakhasiMin],[MorakhasiPrice],[MorakhasiMinUsed],[GheybatMin],[GheybatPrice],[KasrMin],[KasrMin1],[KasrMin2],[KasrMin3],[KasrPrice],[KasrPrice1],[KasrPrice2],[KasrPrice3],[IsPrint],[SumKarkerd],[SumMazaya],[SumKosorat],[SumKhales],[MissionPrice],[MissionMin],CountKarKerdBime,CountKarKerdMaliat, [CountKarKerd],[CountDays],[CountShift],[CountGheybat],[CountNaghes],[CountTatil], [CountMorakhasiWithHoghogh],[CountMorakhasiNotHoghogh],[JsonFishDet],CountMorakhasi,VacationRemind)
	Values
		(@PersonID, @FishNO, @DateM, @DateStartM, @DateEndM, @UID, @IDSanad, @Description, @ST,@VacationST,@EditST, @KarkerdMin, @KarkerdPrice, @EzafeMin, @EzafeMin1, @EzafeMin2, @EzafeMin3, @EzafePrice, @EzafePrice1, @EzafePrice2, @EzafePrice3, @ShabMin, @ShabPrice, @NobatMin1, @NobatPrice1, @NobatMin2, @NobatPrice2, @NobatMin3, @NobatPrice3, @JomeMin,@TatilMin,@Mozafimin,@JarimeRoz, @JomePrice,@TatilPrice,@JarimePrice, @MorakhasiMin, @MorakhasiPrice, @MorakhasiMinUsed,  @GheybatMin, @GheybatPrice, @KasrMin, @KasrMin1, @KasrMin2, @KasrMin3, @KasrPrice, @KasrPrice1, @KasrPrice2, @KasrPrice3, @IsPrint, @SumKarkerd, @SumMazaya, @SumKosorat, @SumKhales, @MissionPrice , @MissionRoz,@CountKarKerdBime,@CountKarKerdMaliat, @CountKarKerd, @CountDays, @CountShift, @CountGheybat, @CountNaghes, @CountTatil,  @CountMorakhasiWithHoghogh , @CountMorakhasiNotHoghogh, @JsonFishDet,@CountMorakhasi,@VacationRemind) 

		
	update person
		set sentToServerStatus = 0
		where id = @PersonID

	Select @@IDENTITY
	Return @@IDENTITY
End
GO
-- ==========================================================================================
create or Alter Procedure [dbo].[sp_Fish_SelectAll]
	@personIDs nvarchar(max),
	@startDate datetime,
	@endDate datetime
As
Begin
	if @personIDs = ''
		SELECT Fish.*, Person.[Name], Person.[Family], Person.FatherName, Person.SHSH, Person.CodeMeli, 
			dbo.Person.CodeMoein, dbo.Person.CodeTafsil, dbo.Person.FullName, Per_WorkTitle.[Name] AS JobTitle
		FROM Fish INNER JOIN
			Person ON Fish.PersonID = Person.ID inner join 
			Gharardad ON Fish.PersonID = Gharardad.PersonID 
			and (Fish.DateStartM between Gharardad.[DateStartM] and Gharardad.[DateFinishM] 
				or Gharardad.[DateStartM] between Fish.DateStartM and Fish.DateEndM) LEFT OUTER JOIN
			Per_WorkTitle ON Gharardad.JobID = Per_WorkTitle.ID
		WHERE (Fish.ST > 0) and (dbo.Fish.DateM between @startDate and @endDate)
		ORDER BY dbo.Fish.[DateM] desc, dbo.Fish.[ID] desc , dbo.Person.Family , dbo.Person.[Name]
	else
		SELECT Fish.*, Person.[Name], Person.[Family], Person.FatherName, Person.SHSH, Person.CodeMeli, 
			dbo.Person.CodeMoein, dbo.Person.CodeTafsil, dbo.Person.FullName, Per_WorkTitle.[Name] AS JobTitle
		FROM Fish INNER JOIN
			Person ON Fish.PersonID = Person.ID inner join 
			(select item from dbo.SplitStrings(@personIDs,',')) as a on dbo.Fish.[PersonID] = cast(a.item as int) INNER JOIN
			Gharardad ON Fish.PersonID = Gharardad.PersonID 
			and (Fish.DateStartM between Gharardad.[DateStartM] and Gharardad.[DateFinishM] 
				or Gharardad.[DateStartM] between Fish.DateStartM and Fish.DateEndM) LEFT OUTER JOIN
			Per_WorkTitle ON Gharardad.JobID = Per_WorkTitle.ID
		WHERE (Fish.ST > 0) and (dbo.Fish.DateM between @startDate and @endDate)
		ORDER BY dbo.Fish.[DateM] desc, dbo.Fish.[ID] desc , dbo.Person.Family , dbo.Person.[Name]
End
GO
-- ==========================================================================================
create or Alter Procedure [dbo].[sp_Fish_SelectAllForInsurance]
	@personIDs nvarchar(Max),
	@startDate datetime,
	@endDate datetime
As
Begin
	if @personIDs = ''
		SELECT Fish.*, Person.[Name], Person.[Family], Person.FatherName, Person.SHSH, Person.CodeMeli, 
			dbo.Person.CodeMoein, dbo.Person.CodeTafsil, dbo.Person.FullName, Per_WorkTitle.[Name] AS JobTitle
		FROM Fish INNER JOIN
			Person ON Fish.PersonID = Person.ID inner join 
			Gharardad ON Fish.PersonID = Gharardad.PersonID 
			and (Fish.DateStartM between Gharardad.[DateStartM] and Gharardad.[DateFinishM] 
				or Gharardad.[DateStartM] between Fish.DateStartM and Fish.DateEndM) LEFT OUTER JOIN
			Per_WorkTitle ON Gharardad.JobID = Per_WorkTitle.ID
		WHERE (Fish.ST > 0) and (dbo.Fish.[DateStartM] between @startDate and @endDate 
		or  dbo.Fish.[DateEndM] between @startDate and @endDate  )
		ORDER BY dbo.Fish.[DateM] desc, dbo.Fish.[ID] desc , dbo.Person.Family , dbo.Person.[Name]
	else
		SELECT Fish.*, Person.[Name], Person.[Family], Person.FatherName, Person.SHSH, Person.CodeMeli, 
			dbo.Person.CodeMoein, dbo.Person.CodeTafsil, dbo.Person.FullName, Per_WorkTitle.[Name] AS JobTitle
		FROM Fish INNER JOIN
			Person ON Fish.PersonID = Person.ID inner join 
			(select item from dbo.SplitStrings(@personIDs,',')) as a on dbo.Fish.[PersonID] = cast(a.item as int) INNER JOIN
			Gharardad ON Fish.PersonID = Gharardad.PersonID 
			and (Fish.DateStartM between Gharardad.[DateStartM] and Gharardad.[DateFinishM] 
				or Gharardad.[DateStartM] between Fish.DateStartM and Fish.DateEndM) LEFT OUTER JOIN
			Per_WorkTitle ON Gharardad.JobID = Per_WorkTitle.ID
		WHERE (Fish.ST > 0) and (dbo.Fish.[DateStartM] between @startDate and @endDate 
		or  dbo.Fish.[DateEndM] between @startDate and @endDate  )
		ORDER BY dbo.Fish.[DateM] desc, dbo.Fish.[ID] desc , dbo.Person.Family , dbo.Person.[Name]
End
GO
