create or Alter Procedure [dbo].[sp_Fish_SelectRow]
	@ID int
As
Begin
	SELECT Fish.*, Person.[Name], Person.[Family], Person.FatherName, Person.SHSH, Person.CodeMeli, 
		dbo.Person.CodeMoein, dbo.Person.CodeTafsil, dbo.Person.FullName, Per_WorkTitle.[Name] AS JobTitle
	FROM Fish INNER JOIN
		Person ON Fish.PersonID = Person.ID inner join 
		Gharardad ON Fish.PersonID = Gharardad.PersonID 
		and (Fish.DateStartM between Gharardad.[DateStartM] and Gharardad.[DateFinishM] 
			or Gharardad.[DateStartM] between Fish.DateStartM and Fish.DateEndM) LEFT OUTER JOIN
		Per_WorkTitle ON Gharardad.JobID = Per_WorkTitle.ID
	Where [dbo].[Fish].[ID] = @ID
End
GO
-- ==========================================================================================
create or Alter PROCEDURE [dbo].[sp_Fish_STIPrint] 
	@ID int
	AS
BEGIN
	SET NOCOUNT ON;
		SELECT [dbo].[Fish].ID AS [ردیف فیش], 
		[dbo].[Fish].FishNO AS [شماره فیش], 
		cast([dbo].[Fish].DateM as date) AS [تاریخ ثبت میلادی], 
		[dbo].DateM2DateSh(dbo.[Fish].DateM) AS [تاریخ ثبت شمسی], 
		[dbo].DateM2DateGh(dbo.[Fish].DateM) AS [تاریخ ثبت قمری], 
		cast([dbo].[Fish].DateStartM as date) AS [از تاریخ میلادی],
		[dbo].DateM2DateSh([dbo].[Fish].DateStartM) AS [از تاریخ شمسی], 
		[dbo].DateM2DateGh([dbo].[Fish].DateStartM) AS [از تاریخ قمری], 
		cast([dbo].[Fish].DateEndM as date) AS [تا تاریخ میلادی],
		[dbo].DateM2DateSh([dbo].[Fish].DateEndM) AS [تا تاریخ شمسی], 
		[dbo].DateM2DateGh([dbo].[Fish].DateEndM) AS [تا تاریخ قمری],
		
		[dbo].[Fish].[Description] AS [شرح فیش],
		[dbo].[Person].ID AS [ردیف پرسنل], 
		[dbo].[Person].CodeTafsil AS [کد پرسنلی], 
		[dbo].[Person].FullName AS [ نام ونام خانوادگی], 
		[dbo].[Person].FatherName AS [نام پدر], 
		cast([dbo].[Person].DateMStartWork as date) AS [تاریخ شروع به کار میلادی], 
		[dbo].DateM2DateSh([dbo].[Person].DateMStartWork) AS [تاریخ شروع به کار شمسی],
		[dbo].DateM2DateGh([dbo].[Person].DateMStartWork) AS [تاریخ شروع به کار قمری],
		cast([dbo].[Person].DateMBirthday as date) AS [تاریخ تولد میلادی], 
		[dbo].DateM2DateSh([dbo].[Person].DateMBirthday) AS [تاریخ تولد شمسی], 
		[dbo].DateM2DateGh([dbo].[Person].DateMBirthday) AS [تاریخ تولد قمری], 
		[dbo].[Person].CodeMeli AS [کد ملی], 
		[dbo].[Person].Adress AS [آدرس پرسنل], 
		[dbo].[Person].Mob1 AS [موبایل 1], 
		[dbo].[Person].Mob2 AS [موبایل 2], 
		[dbo].[Person].Tel1 AS [تلفن 1], 
		[dbo].[Person].Tel2 AS [تلفن 2], 
		[dbo].[Person].NOBimeh AS [شماره بیمه],
 		[dbo].[Gharardad].[NO],
		[dbo].[Gharardad].[CompanyID],
		[dbo].[Gharardad].[Married],
		[dbo].[Gharardad].[CountChild],
		[dbo].[Gharardad].[BankNo],
		[dbo].[Gharardad].[BankID],
		[dbo].[Gharardad].[ShabaNo],
		[dbo].[Gharardad].[BankType],
		[dbo].[Gharardad].[RecruitmentType],
		[dbo].[Gharardad].[PlaceID],
		[dbo].[Gharardad].[IsCheckoutVacation],
		[dbo].[Gharardad].[LeaveMinutes],
		[dbo].[Company].[Name] as CompanyName,
		[dbo].[Bank].[Name] as BankName,
		[dbo].[BankHesabType].[Name] as BankHesabTypeName,
		[dbo].[Per_TypeEstekhdam].[Name] as TypeEstekhdamName,
		[dbo].[Per_KhedmatPlace].[Name] as KhedmatPlaceName,
		[dbo].[Fish].[CountKarKerd] as [روزهای کارکرد],
		[dbo].[Fish].[CountKarKerdBime] as [روزهای کارکرد بیمه],
		[dbo].[Fish].[CountKarKerdMaliat] as [روزهای کارکرد مالیات],
		[dbo].[Fish].KarkerdMin AS [دقایق کارکرد], 
		[dbo].[Fish].KarkerdPrice AS [مبلغ کارکرد], 
		[dbo].[Fish].EzafeMin AS [دقایق اضافه کاری], 
		[dbo].[Fish].EzafePrice AS [مبلغ اضافه کاری], 
		[dbo].[Fish].EzafeMin1 AS [دقایق اضافه کاری اول وقت], 
		[dbo].[Fish].EzafePrice1 AS [مبلغ اضافه کاری اول وقت], 
		[dbo].[Fish].EzafeMin2 AS [دقایق اضافه کاری وسط وقت], 
		[dbo].[Fish].EzafePrice2 AS [مبلغ اضافه کاری وسط وقت], 
		[dbo].[Fish].EzafeMin3 AS [دقایق اضافه کاری آخر وقت], 
		[dbo].[Fish].EzafePrice3 AS [مبلغ اضافه کاری آخر وقت], 
		[dbo].[Fish].ShabMin AS [دقایق شب کاری], 
		[dbo].[Fish].ShabPrice AS [مبلغ شب کاری], 
		[dbo].[Fish].NobatMin1 AS [دقایق نوبت کاری صبح], 
		[dbo].[Fish].NobatPrice1 AS [مبلغ نوبت کاری صبح], 
		[dbo].[Fish].NobatMin2 AS [دقایق نوبت کاری عصر], 
		[dbo].[Fish].NobatPrice2 AS [مبلغ نوبت کاری عصر], 
		[dbo].[Fish].NobatMin3 AS [دقایق نوبت کاری شب], 
		[dbo].[Fish].NobatPrice3 AS [مبلغ نوبت کاری شب], 
		[dbo].[Fish].JomeMin AS [دقایق جمعه کاری], 
		[dbo].[Fish].TatilMin AS [دقایق تعطیل کاری], 
		[dbo].[Fish].Mozafimin AS [دقایق موظفی], 
		[dbo].[Fish].JomePrice AS [مبلغ جمعه کاری], 
		[dbo].[Fish].TatilPrice AS [مبلغ تعطیل کاری], 
		[dbo].[Fish].JarimePrice AS [مبلغ جریمه], 
		[dbo].[Fish].JarimeRoz AS [روزهای جریمه], 
		[dbo].[Fish].MorakhasiMin AS [دقایق کل مرخصی], 
		[dbo].[Fish].CountMorakhasiWithHoghogh AS [روزهای با حقوق], 
		[dbo].[Fish].CountMorakhasiNotHoghogh AS [روزهای مرخصی بدون حقوق], 
		[dbo].[Fish].CountMorakhasi AS [مرخصی روزانه], 
		[dbo].[Fish].MorakhasiPrice AS [مبلغ مرخصی], 
		[dbo].[Fish].MorakhasiMinUsed AS [مرخصی ساعتی], 
		[dbo].[Fish].GheybatMin AS [غیبت روزانه], 
		[dbo].[Fish].GheybatPrice AS [مبلغ غیبت], 
		[dbo].[Fish].KasrMin AS [دقایق کسر کار], 
		[dbo].[Fish].KasrPrice AS [مبلغ کسر کار], 
		[dbo].[Fish].KasrMin1 AS [دقایق کسر کار اول وقت], 
		[dbo].[Fish].KasrPrice1 AS [مبلغ کسر کار اول وقت], 
		[dbo].[Fish].KasrMin2 AS [دقایق کسر کار وسط وقت], 
		[dbo].[Fish].KasrPrice2 AS [مبلغ کسر کار وسط وقت], 
		[dbo].[Fish].KasrMin3 AS [دقایق کسر کار آخر وقت], 
		[dbo].[Fish].KasrPrice3 AS [مبلغ کسر کار آخر وقت], 
		[dbo].[Fish].[MissionMin],
		[dbo].[Fish].[MissionPrice],
		[dbo].[Fish].SumKarkerd AS [مبلغ کل کارکرد], 
		[dbo].[Fish].SumMazaya AS [مبلغ کل مزایا], 
		[dbo].[Fish].SumKosorat AS [مبلغ کل کسورات], 
		[dbo].[Fish].SumKhales AS [مبلغ کل خالص],
		[dbo].[Fish].ST AS [نوع فیش],
		[dbo].[Fish].VacationST AS [نحوه تسویه مرخصی],
		[dbo].[Fish].VacationRemind as [مانده مرخصی]
	FROM [dbo].[Fish] INNER JOIN
		[dbo].[Person] ON [dbo].[Fish].PersonID = [dbo].[Person].ID	INNER JOIN

		[dbo].[Gharardad] ON [dbo].[Gharardad].PersonID = [dbo].[Person].ID 
		and (
			[dbo].[Fish].DateStartM between [dbo].[Gharardad].[DateStartM] and [dbo].[Gharardad].[DateFinishM]
			or [dbo].[Gharardad].[DateStartM] between [dbo].[Fish].DateStartM and [dbo].[Fish].DateEndM
		)
		LEFT OUTER JOIN
		[dbo].[Company] ON [dbo].[Gharardad].[CompanyID] = [dbo].[Company].ID LEFT OUTER JOIN
		[dbo].[Bank] ON [dbo].[Gharardad].[BankID] = [dbo].[Bank].ID LEFT OUTER JOIN
		[dbo].[BankHesabType] ON [dbo].[Gharardad].[BankType] = [dbo].[BankHesabType].ID LEFT OUTER JOIN
		[dbo].[Per_TypeEstekhdam] ON [dbo].[Gharardad].[RecruitmentType] = [dbo].[Per_TypeEstekhdam].ID LEFT OUTER JOIN
		[dbo].[Per_KhedmatPlace] ON [dbo].[Gharardad].[PlaceID] = [dbo].[Per_KhedmatPlace].ID
	where [dbo].[Fish].ID=@ID
END
GO
