create or Alter Procedure [dbo].[sp_Fish_Update_StEdit]
@FishID int,
@UserID int,
@LockState bit
As
Begin
declare @id int
	if(@LockState ='true')
		begin
			select @id = id from dbo.Fish where id = @FishId and EditST = 1
		
			if(ISNULL( @id,0) >0) --اگر قبلا قفل شده است
				begin
					select 2  --قبلا قفل شده 
					return 2
				end
			else --می تواند الان قفل شود
				begin
					Update dbo.Fish 
						Set EditST = @LockState ,UID = @UserID
					where ID = @FishId 
					if(@@ROWCOUNT>0) --با موفقیت قفل شد
						begin
							select 1 --قفل شد
							return 1
						end
					else --خطا در قفل کردن
						begin
							select 0 --خطا
							return 0
					end
				end
		end
	else --قفل باز شود
		begin
			select @id = id from dbo.Fish where id = @FishId  and ( UID = @UserID or UID is null)
		
			if(ISNULL( @id,0) >0) --امکان بازکردن قفل توسط این کاربر هست
				begin
					Update dbo.Fish 
						Set EditST = @LockState ,UID = @UserID
					where ID = @FishId 
					if(@@ROWCOUNT>0) --با موفقیت باز شد
						begin
							select 1
							return 1
						end
					else --خطا در باز کردن
						begin
							select 0
							return 0
					end
				end
	
		else
			begin
				select 3 --عدم دسترسی
				return 3
			end	
	End
end
GO
