create or Alter Procedure [dbo].[sp_FishHesab_Save]
	@ID int,
	@Name nvarchar(200),
	@Type smallint,
	@HTreeID int,
	@Description nvarchar(MAX),
	@ST bit,
	@Account decimal(18,3),
	@CodeTafsil bigint,
	@CodeMoein bigint,
	@Taxable bit,
	@Insurance bit,
	@PrsnTafsilUsed bit

As
Begin
		Update dbo.FishHesab
		Set
			[Name] = @Name,
			[Type] = @Type,
			[HTreeID] = @HTreeID,
			[Description] = @Description,
			[ST] = @ST,
			[Account] = @Account,
			[CodeTafsil]=@CodeTafsil,
			[CodeMoein]=@CodeMoein,
			[Taxable] =  @Taxable,
			[Insurance] = @Insurance,
			[PrsnTafsilUsed] = @PrsnTafsilUsed
		Where [ID] = @ID

	if @@rowcount = 0

		Insert Into FishHesab
				([Name],[Type],[HTreeID],[Description],[ST],[Account],[CodeTafsil],[CodeMoein],[Taxable],[Insurance], [PrsnTafsilUsed])
			Values
				(@Name, @Type, @HTreeID, @Description, @ST, @Account, @CodeTafsil, @CodeMoein, @Taxable, @Insurance, @PrsnTafsilUsed)

	Select @@IDENTITY
	Return @@IDENTITY

End
GO
