create or Alter Procedure [dbo].[sp_FishMali_Insert]
	@HesabID int,
	@FishID int,
	@Debit decimal(18,3),
	@Credit decimal(18,3),
	@Description nvarchar(MAX),
	@Type smallint,
	@ISDecrease bit
As
Begin
	declare @sw int
	select @sw = [FishID]
	from [dbo].[FishMali]
	Where [FishID] = @FishID and [HesabID] = @HesabID
	if (isnull(@sw,0)=0)
	begin
		Insert Into FishMali
			([HesabID],[FishID],[Debit],[Credit],[Description],[Type], [ISDecrease])
		Values
			(@HesabID, @FishID, @Debit, @Credit, @Description, @Type, @ISDecrease)
		Select @@IDENTITY
		Return @@IDENTITY
	end
	else
	begin
		return 0 
	end
End
GO
