create or Alter Procedure [dbo].[sp_Gharardad_Insert]
	@NO nvarchar(50),
	@Peyvast nvarchar(500),
	@DateM datetime,
	@PersonID int,
	@CompanyID smallint,
	@ShiftID smallint,
	@Description nvarchar(MAX),
	@DateStartM	datetime=getdate ,
	@DateFinishM	datetime=getdate,
	@JobID int,
	@Married bit,
	@CountChild smallint,
	@PartID smallint,
	@RecruitmentST smallint,
	@GharardadStatus smallint,
	@RecruitmentType smallint,
	@PlaceID smallint,
	@BankType smallint,
	@BankID smallint,
	@BankNo nvarchar(100),
	@ShabaNo nvarchar(50),
	@SalaryType smallint,
	@Salary    decimal(18, 3),
	@PriceOverTime    decimal(18, 3),
	@PriceOverTime2    decimal(18, 3),
	@PriceOverTime3    decimal(18, 3),
	@PriceNight    decimal(18, 3),
	@PriceNobatKari1    decimal(18, 3),
	@PriceNobatKari2   decimal(18, 3),
	@PriceNobatKari3   decimal(18, 3),
	@PriceHoliday    decimal(18, 3),
	@PriceTatil    decimal(18, 3),
	@PriceJarime    decimal(18, 3),
	@PriceLeave    decimal(18, 3),
	@PriceAbsent    decimal(18, 3),
	@PriceMission    decimal(18, 3),
	@PriceLowTime    decimal(18, 3),
	@PriceLowTime2    decimal(18, 3),
	@PriceLowTime3    decimal(18, 3),
	@LeaveDays float ,
	@LeaveSaved float ,
	@LeaveMinutes smallint,
	@Sanavat smallint,
	@GroupSanavat smallint,
	@isHeadFamily bit,
	@MoeenEmployerInsurance [nvarchar](50) ,
	@TafzilEmployerInsurance [nvarchar](50),
	@ZaribEmployerInsurance float ,
	@MoeenInsuredInsurance [nvarchar],
	@TafzilInsuredInsurance [nvarchar](50) ,
	@ZaribInsuredInsurance float ,
	@MoeenUnemploymentInsurance [nvarchar](50) ,
	@TafzilUnemploymentInsurance [nvarchar](50) ,
	@ZaribUnemploymentInsurance float ,
	@IsPayMalist smallint,
	@IsCheckoutVacation bit,
	@JsonGharardadDet [nvarchar](max)
As
Begin
	if @ShiftID <= 0 and  @ShiftID <> -1
	 set @ShiftID = null 
	if @JobID <= 0
	 set @JobID = null 
	if @PartID <= 0
	 set @PartID = null 
	if @RecruitmentST <= 0
	 set @RecruitmentST = null 
	if @RecruitmentType <= 0
	 set @RecruitmentType = null 
	if @PlaceID <= 0
	 set @PlaceID = null 
	if @BankType <= 0
	 set @BankType = null 
	if @BankID <= 0
	 set @BankID = null 
	if @SalaryType <= 0
	 set @SalaryType = null 
	if @GroupSanavat <= 0
	 set @GroupSanavat = null 
	
	Insert Into dbo.Gharardad
	([NO], Peyvast, DateM,  PersonID, CompanyID, ShiftID, [Description], DateStartM, DateFinishM, JobID, Married, CountChild, PartID, RecruitmentST,GharardadStatus, RecruitmentType, PlaceID, BankType, BankID, BankNo, ShabaNo, SalaryType, Salary, PriceOverTime, PriceOverTime2, PriceOverTime3, PriceNight, PriceNobatKari1, PriceNobatKari2, PriceNobatKari3, PriceHoliday, PriceTatil,PriceJarime, PriceLeave, PriceAbsent,PriceMission, PriceLowTime, PriceLowTime2, PriceLowTime3, LeaveDays, LeaveSaved, LeaveMinutes, Sanavat, GroupSanavat, isHeadFamily,       MoeenEmployerInsurance , TafzilEmployerInsurance,	ZaribEmployerInsurance ,MoeenInsuredInsurance ,TafzilInsuredInsurance ,ZaribInsuredInsurance ,MoeenUnemploymentInsurance ,TafzilUnemploymentInsurance,ZaribUnemploymentInsurance ,IsPayMalist, [JsonGharardadDet],[IsCheckoutVacation])
	select
	@NO, @Peyvast,@DateM, @PersonID,@CompanyID,@ShiftID,@Description,  @DateStartM,@DateFinishM, @JobID,@Married,@CountChild,@PartID,@RecruitmentST,@GharardadStatus,@RecruitmentType,@PlaceID,@BankType,@BankID,@BankNo,@ShabaNo,@SalaryType,@Salary,@PriceOverTime,@PriceOverTime2,@PriceOverTime3,@PriceNight,@PriceNobatKari1,@PriceNobatKari2,@PriceNobatKari3,@PriceHoliday,@PriceTatil,@PriceJarime,@PriceLeave,@PriceAbsent,@PriceMission,@PriceLowTime,@PriceLowTime2,@PriceLowTime3,@LeaveDays,@LeaveSaved,@LeaveMinutes, @Sanavat, @GroupSanavat, @isHeadFamily,@MoeenEmployerInsurance,@TafzilEmployerInsurance,@ZaribEmployerInsurance,@MoeenInsuredInsurance,@TafzilInsuredInsurance,@ZaribInsuredInsurance,@MoeenUnemploymentInsurance,@TafzilUnemploymentInsurance,@ZaribUnemploymentInsurance,@IsPayMalist, @JsonGharardadDet,@IsCheckoutVacation

	
	update person
		set sentToServerStatus = 0
		where id = @PersonID


	Select @@IDENTITY
	Return @@IDENTITY
End
GO
