create or Alter Procedure [dbo].[sp_Gharardad_PrintList]
@GharardadID  int
As
Begin
declare @ShiftID as smallint;
if (@GharardadID =0)--نمایش کل قرارداد های شرکت
	begin
		SELECT dbo.Gharardad.ID, dbo.Gharardad.[NO], dbo.Gharardad.Peyvast, dbo.Gharardad.DateM
				, dbo.Gharardad.PersonID, dbo.Gharardad.CompanyID, dbo.Gharardad.ShiftID, dbo.Gharardad.[Description]
				, dbo.Gharardad.DateStartM, dbo.Gharardad.DateFinishM, dbo.Gharardad.JobID
				, dbo.Gharardad.Married, dbo.Gharardad.CountChild, dbo.Gharardad.PartID, dbo.Gharardad.RecruitmentST,dbo.Gharardad.GharardadStatus
				, dbo.Gharardad.RecruitmentType, dbo.Gharardad.PlaceID, dbo.Gharardad.BankType, dbo.Gharardad.BankID
				, dbo.Gharardad.BankNo, dbo.Gharardad.ShabaNo, dbo.Gharardad.SalaryType, dbo.Gharardad.Salary
				, dbo.Gharardad.PriceOverTime, dbo.Gharardad.PriceOverTime2, dbo.Gharardad.PriceOverTime3
				, dbo.Gharardad.PriceNight, dbo.Gharardad.PriceNobatKari1, dbo.Gharardad.PriceNobatKari2, dbo.Gharardad.PriceNobatKari3, dbo.Gharardad.PriceHoliday, dbo.Gharardad.PriceTatil, dbo.Gharardad.PriceJarime
				, dbo.Gharardad.PriceLeave, dbo.Gharardad.PriceAbsent, dbo.Gharardad.PriceMission
				, dbo.Gharardad.PriceLowTime, dbo.Gharardad.PriceLowTime2, dbo.Gharardad.PriceLowTime3, dbo.Gharardad.LeaveDays
				, dbo.Gharardad.LeaveSaved, dbo.Gharardad.LeaveMinutes, dbo.Gharardad.Sanavat, dbo.Gharardad.GroupSanavat
				,dbo.Gharardad.isHeadFamily, dbo.Person.FullName, dbo.Gharardad.IsCheckoutVacation
		--, dbo.Person.ID AS PersonID
		FROM dbo.Gharardad INNER JOIN
		dbo.Person ON dbo.Gharardad.PersonID = dbo.Person.ID 
		order by dbo.Gharardad.DateM asc 
	end
else -- نمایش قرارداد های یک شخص
	begin
			SELECT  dbo.Gharardad.ID, dbo.Gharardad.[NO], dbo.Gharardad.Peyvast, dbo.Gharardad.DateM
					, dbo.Gharardad.PersonID, dbo.Gharardad.CompanyID, dbo.Gharardad.ShiftID, dbo.Gharardad.[Description]
					, dbo.Gharardad.DateStartM, dbo.Gharardad.DateFinishM, dbo.Gharardad.JobID
					, CASE WHEN dbo.Gharardad.Married = 0 THEN N'مجرد' ELSE N'متاهل' END AS Mariage, dbo.Gharardad.CountChild
					, dbo.Gharardad.PartID, dbo.Gharardad.RecruitmentST,dbo.Gharardad.GharardadStatus, dbo.Gharardad.RecruitmentType, dbo.Gharardad.PlaceID
					, dbo.Gharardad.BankType, dbo.Gharardad.BankID, dbo.Gharardad.BankNo, dbo.Gharardad.ShabaNo, dbo.Gharardad.SalaryType
					, dbo.Gharardad.Salary
					, dbo.Gharardad.PriceOverTime, dbo.Gharardad.PriceOverTime2, dbo.Gharardad.PriceOverTime3, dbo.Gharardad.PriceNight
					, dbo.Gharardad.PriceNobatKari1, dbo.Gharardad.PriceNobatKari2, dbo.Gharardad.PriceNobatKari3
					, dbo.Gharardad.PriceHoliday, dbo.Gharardad.PriceTatil, dbo.Gharardad.PriceJarime , dbo.Gharardad.PriceLeave, dbo.Gharardad.PriceAbsent, dbo.Gharardad.PriceMission
					, dbo.Gharardad.PriceLowTime, dbo.Gharardad.PriceLowTime2, dbo.Gharardad.PriceLowTime3
					, dbo.Gharardad.LeaveDays, dbo.Gharardad.LeaveSaved, dbo.Gharardad.LeaveMinutes, dbo.Gharardad.Sanavat, dbo.Gharardad.GroupSanavat
					,dbo.Gharardad.isHeadFamily, dbo.Gharardad.IsCheckoutVacation, dbo.Person.FullName
					, dbo.Person.Name, dbo.Person.Family, dbo.Person.FullName, dbo.Person.FatherName, dbo.Person.DateMBirthday
					, dbo.Person.CodeMeli, dbo.Person.Adress, dbo.Person.SodorSH, dbo.Person.SHSH, dbo.Per_Khedmat.Name AS RecruitmentName
					, dbo.Per_WorkTitle.Name AS jobName, dbo.Company.Name AS CompanyName, dbo.Company.NameKarfarma as KarfarmaName
					, dbo.Company.[Address] AS CompanyAddress, dbo.ShiftDet.[ShiftID], dbo.[ShiftCodeing].H1, dbo.[ShiftCodeing].M1 AS MShift1
					, dbo.[ShiftCodeing].H2, dbo.[ShiftCodeing].M2, dbo.ShiftDet.Sat, dbo.ShiftDet.Sun, dbo.ShiftDet.Mon
					, dbo.ShiftDet.Tue, dbo.ShiftDet.Wed, dbo.ShiftDet.Tur, dbo.ShiftDet.Fri, dbo.ShiftDet.FriType,dbo.Person.MadrakTahsili
				FROM dbo.Gharardad INNER JOIN
					dbo.Person ON dbo.Gharardad.PersonID = dbo.Person.ID left outer JOIN
					dbo.Per_WorkTitle ON dbo.Gharardad.PlaceID = dbo.Per_WorkTitle.ID  left outer JOIN
					dbo.Company ON dbo.Gharardad.CompanyID = dbo.Company.ID left outer JOIN
					dbo.Shifts ON dbo.Gharardad.ShiftID = dbo.Shifts.ID LEFT OUTER JOIN
					dbo.ShiftDet ON dbo.Shifts.ID = dbo.ShiftDet.ShiftID LEFT OUTER JOIN
					dbo.[ShiftCodeing] ON dbo.ShiftDet.[ShiftCodingID] = dbo.[ShiftCodeing].ID LEFT OUTER JOIN
					dbo.Per_Khedmat ON dbo.Gharardad.RecruitmentST = dbo.Per_Khedmat.ID 

			where dbo.Gharardad.ID=@GharardadID 
			order by dbo.Gharardad.DateM desc
		 --end
	end
End
GO
-- ==========================================================================================
create or Alter Procedure [dbo].[sp_Gharardad_SelectAll]
	@lstPersonIds nvarchar(Max),
	@startDate datetime,
	@endDate datetime 
As
Begin
	IF @lstPersonIds = ''
		SELECT dbo.Gharardad.*
		FROM dbo.Gharardad INNER JOIN
		dbo.Person ON dbo.Gharardad.PersonID = dbo.Person.ID 
		where (@startDate between  [DateStartM] and [DateFinishM] )	or ([DateStartM] between @startDate and @endDate) and dbo.Person.ST=1
		order by Person.Family ,person.Name ,dbo.Gharardad.[DateStartM] desc 
	else
		SELECT dbo.Gharardad.*
		FROM dbo.Gharardad INNER JOIN
		dbo.Person ON dbo.Gharardad.PersonID = dbo.Person.ID inner join
		(select item from dbo.SplitStrings(@lstPersonIds,',')) as a on dbo.Gharardad.[PersonID]  = a.item 
		where (@startDate between  [DateStartM] and [DateFinishM] )	or ([DateStartM] between @startDate and @endDate)
		order by Person.Family ,person.Name ,dbo.Gharardad.[DateStartM] desc 
End
GO
-- ==========================================================================================
create or Alter Procedure [dbo].[sp_Gharardad_SelectCheckout]
	@lstPersonIds nvarchar(Max),
	@startDate datetime,
	@endDate datetime 
As
Begin
	IF @lstPersonIds = ''
		SELECT gh.NO as ContractNo,gh.PersonID,pe.FullName
		FROM dbo.Gharardad as gh INNER JOIN
		dbo.Person as pe ON gh.PersonID = pe.ID 
		where DateFinishM between @startDate and @endDate 
		order by gh.DateFinishM desc ,gh.NO 
	else
		SELECT gh.NO as ContractNo,gh.PersonID,pe.FullName
		FROM dbo.Gharardad as gh INNER JOIN
		dbo.Person as pe ON gh.PersonID = pe.ID  inner join
		(select item from dbo.SplitStrings(@lstPersonIds,',')) as a on gh.PersonID = a.item 
		where DateFinishM between @startDate and @endDate 
		order by gh.DateFinishM desc ,gh.NO 
End

GO
