create or Alter Procedure [dbo].[sp_Gharardad_Update]
	@ID int,
	@NO nvarchar(50),
	@Peyvast nvarchar(500),
	@DateM datetime,
	@PersonID int,
	@CompanyID smallint,
	@ShiftID smallint,
	@Description nvarchar(MAX),
	@DateStartM	datetime=getdate,
	@DateFinishM datetime=getdate,
	@JobID int,
	@Married bit,
	@CountChild smallint,
	@PartID smallint,
	@RecruitmentST smallint,
	@GharardadStatus smallint,
	@RecruitmentType smallint,
	@PlaceID smallint,
	@BankType smallint,
	@BankID smallint,
	@BankNo nvarchar(100),
	@ShabaNo nvarchar(50),
	@SalaryType smallint,
	@Salary    decimal(18, 3),
	@PriceOverTime    decimal(18, 3),
	@PriceOverTime2    decimal(18, 3),
	@PriceOverTime3    decimal(18, 3),
	@PriceNight    decimal(18, 3),
	@PriceNobatKari1    decimal(18, 3),
	@PriceNobatKari2    decimal(18, 3),
	@PriceNobatKari3    decimal(18, 3),
	@PriceHoliday    decimal(18, 3),
	@PriceTatil    decimal(18, 3),
	@PriceJarime    decimal(18, 3),
	@PriceLeave    decimal(18, 3),
	@PriceAbsent    decimal(18, 3),
	@PriceMission    decimal(18, 3),
	@PriceLowTime    decimal(18, 3),
	@PriceLowTime2    decimal(18, 3),
	@PriceLowTime3    decimal(18, 3),
	@LeaveDays float,
	@LeaveSaved float,
	@LeaveMinutes smallint,
	@Sanavat smallint,
	@GroupSanavat smallint,
	@isHeadFamily bit,
	@MoeenEmployerInsurance [nvarchar](50) ,
	@TafzilEmployerInsurance [nvarchar](50),
	@ZaribEmployerInsurance float ,
	@MoeenInsuredInsurance [nvarchar],
	@TafzilInsuredInsurance [nvarchar](50) ,
	@ZaribInsuredInsurance float ,
	@MoeenUnemploymentInsurance [nvarchar](50) ,
	@TafzilUnemploymentInsurance [nvarchar](50) ,
	@ZaribUnemploymentInsurance float ,
	@IsPayMalist smallint,
	@IsCheckoutVacation bit,
	@JsonGharardadDet [nvarchar](max)
As
Begin
	if @ShiftID <= 0 and  @ShiftID <> -1
	 set @ShiftID = null 
	if @JobID <= 0
	 set @JobID = null 
	if @PartID <= 0
	 set @PartID = null 
	if @RecruitmentST <= 0
	 set @RecruitmentST = null 
	if @RecruitmentType <= 0
	 set @RecruitmentType = null 
	if @PlaceID <= 0
	 set @PlaceID = null 
	if @BankType <= 0
	 set @BankType = null 
	if @BankID <= 0
	 set @BankID = null 
	if @SalaryType <= 0
	 set @SalaryType = null 
	if @GroupSanavat <= 0
	 set @GroupSanavat = null 

	Update dbo.Gharardad
	Set
		[NO] = @NO,
		[Peyvast] = @Peyvast,
		[DateM] = @DateM,
		[PersonID] = @PersonID,
		[CompanyID] = @CompanyID,
		[ShiftID] = @ShiftID,
		[Description] = @Description,
		[DateStartM]=@DateStartM,
		[DateFinishM]=@DateFinishM,
		[JobID] = @JobID,
		[Married] = @Married,
		[CountChild] = @CountChild,
		[PartID] = @PartID,
		[RecruitmentST] = @RecruitmentST,
		[GharardadStatus] = @GharardadStatus,
		[RecruitmentType] = @RecruitmentType,
		[PlaceID] = @PlaceID,
		[BankType] = @BankType,
		[BankID] = @BankID,
		[BankNo] = @BankNo,
		[ShabaNo] = @ShabaNo,
		[SalaryType] = @SalaryType,
		[Salary] = @Salary,
		[PriceOverTime] = @PriceOverTime,
		[PriceOverTime2] = @PriceOverTime2,
		[PriceOverTime3] = @PriceOverTime3,
		[PriceNight] = @PriceNight,
		[PriceNobatKari1] = @PriceNobatKari1,
		[PriceNobatKari2] = @PriceNobatKari2,
		[PriceNobatKari3] = @PriceNobatKari3,
		[PriceHoliday] = @PriceHoliday,
		[PriceTatil] = @PriceTatil,
		[PriceJarime] = @PriceJarime,
		[PriceLeave] = @PriceLeave,
		[PriceAbsent] = @PriceAbsent,
		[PriceMission] = @PriceMission,
		[PriceLowTime] = @PriceLowTime,
		[PriceLowTime2] = @PriceLowTime2,
		[PriceLowTime3] = @PriceLowTime3,
		[LeaveDays] = @LeaveDays,
		[LeaveSaved] = @LeaveSaved,
		[LeaveMinutes] = @LeaveMinutes, 
		[Sanavat] = @Sanavat,
		[GroupSanavat] = @GroupSanavat,
		[isHeadFamily] = @isHeadFamily,
		[MoeenEmployerInsurance] = @MoeenEmployerInsurance,              
		[TafzilEmployerInsurance] = @TafzilEmployerInsurance,
		[ZaribEmployerInsurance] = @ZaribEmployerInsurance,
		[MoeenInsuredInsurance] = @MoeenInsuredInsurance ,
		[TafzilInsuredInsurance] = @TafzilInsuredInsurance,
		[ZaribInsuredInsurance] = @ZaribInsuredInsurance,
		[MoeenUnemploymentInsurance] = @MoeenUnemploymentInsurance,
		[TafzilUnemploymentInsurance] = @TafzilUnemploymentInsurance,
		[ZaribUnemploymentInsurance] = @ZaribUnemploymentInsurance,
		[IsPayMalist] = @IsPayMalist ,
		[IsCheckoutVacation] = @IsCheckoutVacation,
		[JsonGharardadDet] = @JsonGharardadDet
	Where [ID] = @ID

	
	update person
		set sentToServerStatus = 0
		where id = @PersonID

End
GO

-- ==========================================================================================
create or Alter Procedure [dbo].[sp_Gharardad_Valid]
	@CurrDate Date
	, @DeviceId int
As
Begin
	SELECT dbo.Gharardad.ID as GharardadId, 
		dbo.Gharardad.[NO] as GharardadNo, 
		dbo.Gharardad.PersonID, 
		dbo.Gharardad.ShiftID, 
		dbo.Person.FullName, 
		dbo.Person.CodeMeli, 
		dbo.EnrollData.EnrollData,
		dbo.Shifts.[Name] as ShiftName, 
		dbo.Shifts.PackageType, 
		dbo.Shifts.Periodic, 
		dbo.Shifts.PackageGuid, 
		dbo.ShiftDet.ShiftCodingID, 
		dbo.ShiftDet.Sat, 
		dbo.ShiftDet.Sun, 
		dbo.ShiftDet.Mon, 
		dbo.ShiftDet.Tue, 
		dbo.ShiftDet.Wed, 
		dbo.ShiftDet.Tur, 
		dbo.ShiftDet.Fri, 
		dbo.ShiftDet.FriType, 
		dbo.ShiftCodeing.H1, 
		dbo.ShiftCodeing.M1, 
		dbo.ShiftCodeing.H2, 
		dbo.ShiftCodeing.M2, 
		dbo.ShiftCodeing.TajilKh, 
		dbo.ShiftCodeing.TajilV, 
		dbo.ShiftCodeing.TakhirV, 
		dbo.ShiftCodeing.JarimeV, 
		dbo.ShiftCodeing.TakhirKh, 
		dbo.ShiftCodeing.TypeShift,
		dbo.Gharardad.DateStartM,
		dbo.Gharardad.DateFinishM
	FROM dbo.Gharardad INNER JOIN
		dbo.Person ON dbo.Gharardad.PersonID = dbo.Person.ID INNER JOIN
		dbo.Shifts ON dbo.Gharardad.ShiftID = dbo.Shifts.ID INNER JOIN
		dbo.ShiftDet ON dbo.Shifts.ID = dbo.ShiftDet.ShiftID INNER JOIN
		dbo.ShiftCodeing ON dbo.ShiftDet.ShiftCodingID = dbo.ShiftCodeing.ID inner join
		dbo.EnrollData on dbo.EnrollData.PersonId=dbo.Person.ID and dbo.EnrollData.DeviceId=@DeviceId
	where dbo.Person.ST = 'True'
	and @currDate between cast(dbo.Gharardad.DateStartM as date) and cast(dbo.Gharardad.DateFinishM as date)
	and @currDate between cast(dbo.ShiftDet.DateStartM as date) and cast(dbo.ShiftDet.DateFinishM as date)
	order by fullname
end
GO
