	Delete from [dbo].[GharardadDet]
	Where [GharardadID] = @GharardadID
End
Go
-- ==========================================================================================
create or Alter Procedure [dbo].[sp_GharardadDet_Insert]
	@GharardadID int,
	@HesabID int,
	@Debit    decimal(18, 3),
	@Credit    decimal(18, 3),
	@Order smallint ,
	@Description nvarchar(500),
	@ISDecrease bit
As
Begin

	declare @sw int
	select @sw = GharardadID
	from [dbo].[GharardadDet]
	Where [GharardadID] = @GharardadID and [HesabID] = @HesabID
	if (isnull(@sw,0)=0)
	begin
		Insert Into [dbo].[GharardadDet]
			( GharardadID, HesabID, Debit, Credit, [Order], [Description], [ISDecrease])
		Values
			(@GharardadID, @HesabID, @Debit, @Credit, @Order, @Description, @ISDecrease)
		return 1 
	end
	else
	begin
		return 0 
	end
End
GO
-- ==========================================================================================
create or Alter Procedure [dbo].[sp_GharardadDet_SelectRow]
	@GharardadID int,
	@HesabID int
As
Begin
	Select [dbo].[GharardadDet].GharardadID, [dbo].[GharardadDet].HesabID, [dbo].[GharardadDet].Debit
		, [dbo].[GharardadDet].Credit, [dbo].[GharardadDet].[Order], [dbo].[GharardadDet].[Description], [dbo].[GharardadDet].[ISDecrease]
		, [dbo].[FishHesab].Name, [dbo].[FishHesab].[Type], [dbo].[FishHesab].HTreeID, [dbo].[FishHesab].[Description] as DescFishHesab
		, [dbo].[FishHesab].ST, [dbo].[FishHesab].Account, [dbo].[FishHesab].CodeTafsil, [dbo].[FishHesab].CodeMoein
	From [dbo].[GharardadDet] inner join
		[dbo].[FishHesab] on [dbo].[GharardadDet].[HesabID] = [dbo].[FishHesab].[ID]
	Where [GharardadID] = @GharardadID and [HesabID] = @HesabID
End
GO
-- ==========================================================================================
create or Alter Procedure [dbo].[sp_GharardadDet_SelectRowsByGharardadID]
	@GharardadID int
As
Begin
	Select [dbo].[GharardadDet].GharardadID, [dbo].[GharardadDet].HesabID, [dbo].[GharardadDet].Debit
		, [dbo].[GharardadDet].Credit, [dbo].[GharardadDet].[Order], [dbo].[GharardadDet].[Description], [dbo].[GharardadDet].[ISDecrease]
		, [dbo].[FishHesab].Name, [dbo].[FishHesab].[Type], [dbo].[FishHesab].HTreeID, [dbo].[FishHesab].[Description] as DescFishHesab
		, [dbo].[FishHesab].ST, [dbo].[FishHesab].Account, [dbo].[FishHesab].CodeTafsil, [dbo].[FishHesab].CodeMoein
	From [dbo].[GharardadDet] inner join
		[dbo].[FishHesab] on [dbo].[GharardadDet].[HesabID] = [dbo].[FishHesab].[ID]
	Where [GharardadID] = @GharardadID
	order by [dbo] .[GharardadDet] .[Order] 
End
GO
