create or Alter Procedure [dbo].[sp_HardwareCodeCus_NotDefine]
	@LogonPersonelIDs nvarchar(100)
As
Begin
		select PersonNO
		from LogonPersonel inner join 
		(select item from dbo.SplitStrings(@LogonPersonelIDs,',')) as b on LogonPersonel.ID = cast(b.item as int)
	except
		select HardwareCode
		from HardwareCodeCus
end
go

-- ==========================================================================================
create or Alter Procedure [dbo].[sp_HardwareCodeCus_SelectAll]
As
Begin
		select PersonID,DeviceID,HardwareCode
			from	HardwareCodeCus

		union 

		SELECT  v.PersonID,DeviceID, v.PersonNO as HardwareCode
			FROM 
				(SELECT LogonPersonel.PersonID,DeviceInfo.id as DeviceID, LogonPersonel.PersonNO,
					ROW_NUMBER() OVER (PARTITION BY LogonPersonel.PersonNO,logonpersonel.deviceNo ORDER BY LogonPersonel.DateTimeLogM DESC) AS Rnum
				FROM LogonPersonel
						inner join DeviceInfo on LogonPersonel.DeviceId = DeviceInfo.ID
				WHERE PersonID is null Or PersonID =0) v
				WHERE Rnum=1 
End
GO
-- ==========================================================================================
CREATE OR ALTER   VIEW [dbo].[HardWareCodeCusView]
AS
SELECT    dbo.HardwareCodeCus.PersonID
		, dbo.HardwareCodeCus.DeviceID
		, dbo.HardwareCodeCus.HardwareCode
		, dbo.Person.FullName
		, dbo.DeviceInfo.DeviceName
		, dbo.DeviceInfo.DeviceNO
		, DeviceInfo.Guid As DeviceGuid
		, Person.Guid As PersonGuid
FROM    dbo.HardwareCodeCus 
INNER JOIN dbo.Person ON dbo.HardwareCodeCus.PersonID = dbo.Person.ID 
INNER JOIN dbo.DeviceInfo ON dbo.HardwareCodeCus.DeviceID = dbo.DeviceInfo.ID

UNION

SELECT    v.PersonID
		, DeviceID
		, v.PersonNO AS HardwareCode
		, '' AS FullName
		, DeviceName AS DeviceName
		, DeviceNO
		, v.DeviceGuid
		, null As PersonGuid
FROM    
	(
		SELECT    LogonPersonel.PersonID
				, DeviceInfo.id AS DeviceID
				, LogonPersonel.PersonNO
				, DeviceInfo.DeviceName
				, DeviceInfo.DeviceNO
				, DeviceInfo.Guid As DeviceGuid
				, ROW_NUMBER() OVER (PARTITION BY LogonPersonel.PersonNO, logonpersonel.deviceNo ORDER BY LogonPersonel.DateTimeLogM DESC ) AS Rnum
		FROM LogonPersonel 
		INNER JOIN DeviceInfo ON LogonPersonel.DeviceNO = DeviceInfo.DeviceNO
		WHERE PersonID IS NULL OR PersonID = 0
	) v
WHERE Rnum = 1 
GO
