create or Alter Procedure [dbo].[sp_Holiday_Save]
	@DateM date,
	@Monasebat nvarchar(MAX),
	@Description nvarchar(MAX),
	@STRasmi  bit
As
Begin
	declare @Dow smallint;
	set @Dow=DATEPART(WEEKDAY,@DateM) 
	if(@Dow=6)
		set @STRasmi = 'True'

  IF Not EXISTS( select [DateM] from [dbo].[Holiday]	Where DateM = @DateM )
	begin
		Insert Into Holiday
			([DateM],[Monasebat],[Description],[STRasmi])
		Values
			(@DateM,@Monasebat,@Description,@STRasmi)
	end
	else
	begin
		Update dbo.Holiday
	Set
		[Monasebat] = @Monasebat,
		[Description] = @Description,
		[STRasmi]=@STRasmi,
		Modified=getdate()
		where [DateM] = @DateM
	end
End
GO
