create or Alter Procedure [dbo].[sp_MorakhasiDaily_Show]
	@personIDs nvarchar(Max),
	@Date1 date,
	@Date2 date,
	@Desc nvarchar(500)
As
Begin
	if (@desc='')
	begin
		if (@personIDs='')
			SELECT 
				  MorakhasiDaily.ID
				, MorakhasiDaily.DateM
				, MorakhasiDaily.PersonID
				, MorakhasiDaily.[Desc]
				, MorakhasiDaily.TypeID
				, TypeMorakhasi.Name as TypeMorakhasiName
				, Person.CodeTafsil as PersonCodeTafsil
				, Person.FullName as PersonFullName
				, TypeMorakhasi.Hoghogh as HasHoghogh
				, TypeMorakhasi.Maliyat as HasMaliyat
				, TypeMorakhasi.Bimeh as HasBimeh
				, Person.GUID As PersonGuid
			FROM MorakhasiDaily INNER JOIN
				TypeMorakhasi ON MorakhasiDaily.TypeID = TypeMorakhasi.ID INNER JOIN
				Person ON dbo.MorakhasiDaily.PersonID = Person.ID
			where (dbo.MorakhasiDaily.DateM between @Date1 and @Date2)
			order by MorakhasiDaily.DateM 
		else
			SELECT 
				  MorakhasiDaily.ID
				, MorakhasiDaily.DateM
				, MorakhasiDaily.PersonID
				, MorakhasiDaily.[Desc]
				, MorakhasiDaily.TypeID
				, TypeMorakhasi.Name as TypeMorakhasiName
				, Person.CodeTafsil as PersonCodeTafsil
				, Person.FullName as PersonFullName
				, TypeMorakhasi.Hoghogh as HasHoghogh
				, TypeMorakhasi.Maliyat as HasMaliyat
				, TypeMorakhasi.Bimeh as HasBimeh
				, Person.GUID As PersonGuid
			FROM MorakhasiDaily INNER JOIN
				TypeMorakhasi ON dbo.MorakhasiDaily.TypeID = TypeMorakhasi.ID INNER JOIN
				Person ON dbo.MorakhasiDaily.PersonID = Person.ID inner join 
				(select item from dbo.SplitStrings(@personIDs,',')) as a on MorakhasiDaily.PersonID = cast(a.item as int)
			where (MorakhasiDaily.DateM between @Date1 and @Date2)
			order by MorakhasiDaily.DateM 
	end
	else--شرح پرشده
	begin 
		if (@personIDs='')
			SELECT 
				  MorakhasiDaily.ID
				, MorakhasiDaily.DateM
				, MorakhasiDaily.PersonID
				, MorakhasiDaily.[Desc]
				, MorakhasiDaily.TypeID
				, TypeMorakhasi.Name as TypeMorakhasiName
				, Person.CodeTafsil as PersonCodeTafsil
				, Person.FullName as PersonFullName
				, TypeMorakhasi.Hoghogh as HasHoghogh
				, TypeMorakhasi.Maliyat as HasMaliyat
				, TypeMorakhasi.Bimeh as HasBimeh
				, Person.GUID As PersonGuid
			FROM MorakhasiDaily INNER JOIN
				TypeMorakhasi ON dbo.MorakhasiDaily.TypeID = TypeMorakhasi.ID INNER JOIN
				Person ON dbo.MorakhasiDaily.PersonID = Person.ID 
			where (MorakhasiDaily.DateM between @Date1 and @Date2) and MorakhasiDaily.[Desc] like @Desc 
			order by MorakhasiDaily.DateM 
		else
			SELECT 
				  MorakhasiDaily.ID
				, MorakhasiDaily.DateM
				, MorakhasiDaily.PersonID
				, MorakhasiDaily.[Desc]
				, MorakhasiDaily.TypeID
				, TypeMorakhasi.Name as TypeMorakhasiName
				, Person.CodeTafsil as PersonCodeTafsil
				, Person.FullName as PersonFullName
				, TypeMorakhasi.Hoghogh as HasHoghogh
				, TypeMorakhasi.Maliyat as HasMaliyat
				, TypeMorakhasi.Bimeh as HasBimeh
				, Person.GUID As PersonGuid
			FROM MorakhasiDaily INNER JOIN
				TypeMorakhasi ON MorakhasiDaily.TypeID = TypeMorakhasi.ID INNER JOIN
				Person ON MorakhasiDaily.PersonID = Person.ID inner join 
				(select item from dbo.SplitStrings(@personIDs,',')) as a on MorakhasiDaily.PersonID = cast(a.item as int)
			where (MorakhasiDaily.DateM between @Date1 and @Date2) and MorakhasiDaily.[Desc] like @Desc 
			order by MorakhasiDaily.DateM 
	end
End
GO
