create or Alter Procedure [dbo].[sp_LogonPersonel_DeleteRow]
	@ID int
As
Begin
	declare @IsVirtual smallInt

	select @IsVirtual=IsVirtual from LogonPersonel where id = @ID
	if(@IsVirtual = 4 or @IsVirtual = 6) --taradod virtual that added by system
		Delete LogonPersonel 
		Where [ID] = @ID
	else
		update LogonPersonel -- taradod real that deleted by user
		set IsDeleted = 1
		Where [ID] = @ID
End
GO
-- ========================================================================================

create or Alter Procedure [dbo].[sp_LogonPersonel_DeleteAll]
	@FromDate datetime,
	@ToDate datetime,
	@PersonId int,
	@IsVirtual smallInt
As
Begin

	if(@IsVirtual = 4 or @IsVirtual = 6) --taradod virtual that added by system
		Delete from LogonPersonel 
		Where [PersonID] = @PersonId
				and DateTimeLogM between @FromDate and @ToDate
				and IsVirtual = @IsVirtual
	else
		update LogonPersonel -- taradod real that deleted by user
		set IsDeleted = 1
		Where [PersonID] = @PersonId
				and DateTimeLogM between @FromDate and @ToDate
				and IsVirtual = @IsVirtual
End
GO
-- =============================================
create or Alter procedure [dbo].[sp_LogonPersonel_Duration]
	@personId int,
	@StartDate Date,
	@EndDate Date
As
Begin
	IF OBJECT_ID('tempdb..#Temp') IS not NULL
		drop table #Temp

	SELECT *
	INTO #Temp
	FROM
	(
		SELECT [DateTimeLogM],[PersonID]
		  ,ROW_NUMBER() OVER(PARTITION BY [LogonPersonel].Personid ORDER BY [DateTimeLogM] ) AS radif
		  FROM [dbo].[LogonPersonel]
		  where personId = @personId and cast(DateTimeLogM as date)  between @StartDate and @EndDate
	) as q

	IF OBJECT_ID('tempdb..#Temp2') IS not NULL
		drop table #Temp2
	select * 
	INTO #Temp2
	from
	(
		select q1.Personid, q1.[DateTimeLogM] as DateTimeLogM1, q1.radif as radif1
			,q2.[DateTimeLogM] as DateTimeLogM2, q2.radif as radif2, datediff(minute,  q1.[DateTimeLogM], q2.[DateTimeLogM]) as duration1
			,q3.[DateTimeLogM] as DateTimeLogM3, q3.radif as radif3
			,q4.[DateTimeLogM] as DateTimeLogM4, q4.radif as radif4, datediff(minute,  q3.[DateTimeLogM], q4.[DateTimeLogM]) as duration2
			,q5.[DateTimeLogM] as DateTimeLogM5, q5.radif as radif5
			,q6.[DateTimeLogM] as DateTimeLogM6, q6.radif as radif6, datediff(minute,  q5.[DateTimeLogM], q6.[DateTimeLogM]) as duration3
			,q7.[DateTimeLogM] as DateTimeLogM7, q7.radif as radif7
			,q8.[DateTimeLogM] as DateTimeLogM8, q8.radif as radif8, datediff(minute,  q7.[DateTimeLogM], q8.[DateTimeLogM]) as duration4
		from #temp as q1 left outer join
			#temp as q2 on q1.personid = q2.personid and cast(q1.datetimelogM as date)= cast(q2.datetimelogM as date) and q2.radif = 2 left outer join
			#temp as q3 on q1.personid = q3.personid and cast(q1.datetimelogM as date)= cast(q3.datetimelogM as date) and q3.radif = 3 left outer join
			#temp as q4 on q1.personid = q4.personid and cast(q1.datetimelogM as date)= cast(q4.datetimelogM as date) and q4.radif = 4 left outer join
			#temp as q5 on q1.personid = q5.personid and cast(q1.datetimelogM as date)= cast(q5.datetimelogM as date) and q5.radif = 5 left outer join
			#temp as q6 on q1.personid = q6.personid and cast(q1.datetimelogM as date)= cast(q6.datetimelogM as date) and q6.radif = 6 left outer join
			#temp as q7 on q1.personid = q7.personid and cast(q1.datetimelogM as date)= cast(q7.datetimelogM as date) and q7.radif = 7 left outer join
			#temp as q8 on q1.personid = q8.personid and cast(q1.datetimelogM as date)= cast(q8.datetimelogM as date) and q8.radif = 8 
		where q1.radif = 1
	) as query 
	order by DateTimeLogM1 desc

	select * 
	from
	(
		select Personid, DateTimeLogM1, DateTimeLogM2, duration1 as duration
		from #Temp2
		where DateTimeLogM1 is not null
		union
		select Personid, DateTimeLogM3 as DateTimeLogM1, DateTimeLogM4 as DateTimeLogM2, duration2 as duration
		from #Temp2
		where DateTimeLogM3 is not null
		union
		select Personid, DateTimeLogM5 as DateTimeLogM1, DateTimeLogM6 as DateTimeLogM2, duration3 as duration
		from #Temp2
		where DateTimeLogM5 is not null
		union
		select Personid, DateTimeLogM7 as DateTimeLogM1, DateTimeLogM8 as DateTimeLogM2, duration4 as duration
		from #Temp2
		where DateTimeLogM7 is not null
	) as query 
	order by [DateTimeLogM1] desc
	IF OBJECT_ID('tempdb..#Temp') IS not NULL
		drop table #Temp
	IF OBJECT_ID('tempdb..#Temp2') IS not NULL
		drop table #Temp2
End
GO
