create or Alter Procedure [dbo].[sp_LogonPersonel_Insert]
	@DateTimeLogM datetime,
	@IDTraffic bigint,
	@PersonNO int,
	@DeviceId int,
	@DeviceNo int,
	@Calced bit='true',
	@IsVirtual smallint = 1,
	@TrafficType smallint = 3,
	@TrafficName nvarchar(50) = '',
	@TrafficTypeVacationOrMission smallint=0,
	@GUID uniqueidentifier=null,
	@PersonID  int = 0,
	@DeviceSerial  nvarchar(50) = '',
	@IsDeleted bit = 'false'
As
Begin
if (@PersonID = 0)
	set @PersonID= null
if (isnull(@GUID,'00000000-0000-0000-0000-000000000000')='00000000-0000-0000-0000-000000000000')
	begin
		set @GUID = newid()
	end
	declare @BeforIDForThisTaradod int
	Declare @ReferenceID int
	
	select @BeforIDForThisTaradod=ID
	from LogonPersonel
	WHERE [Guid] = @GUID 

	if (isnull(@BeforIDForThisTaradod,0)>0)
		begin
			set @ReferenceID = @BeforIDForThisTaradod
		end
	else
		begin
			if(@PersonID = 0)
			begin
				select @PersonID=PersonId 
				from HardwareCodeCus inner join DeviceInfo on DeviceInfo.id=HardwareCodeCus.DeviceID
				where DeviceInfo.Id=@DeviceId and HardwareCode=@PersonNO
			end

			if(@IsVirtual not in (5,2) ) -- اگر تردد دستی اضافه نشده پس باید موجود بودن از قبل چک شود
			begin
				select @BeforIDForThisTaradod=ID
				from LogonPersonel
				where [DateTimeLogM]=@DateTimeLogM and [PersonNO]=@PersonNO and @DeviceId=DeviceId 
			end
			--else --اگر تردد توسط کاربر اضافه شده و موجود هست و حالت فعال هم هست دیگر نباید اضافه شود
			--	begin
			--		select @BeforIDForThisTaradod=ID
			--		from LogonPersonel
			--		where [DateTimeLogM]=@DateTimeLogM and [PersonNO]=@PersonNO and @DeviceId=DeviceId 
			--		 and IsDeleted = 0-- اگر از دستگاه تردد آمد شرط حذف شدن یا نشدن نباید چک شود  
			--		-- اما اگر تردد دستی ثبت شود اگر قبلا بوده لیکن حذف شده باشد اجازه ثبت نمیده باید تصمیم گیری شود
			--	end
			
			if (isnull(@BeforIDForThisTaradod,0)=0)
				begin
					if(@TrafficTypeVacationOrMission=0 Or @TrafficTypeVacationOrMission=1 )
						select @TrafficTypeVacationOrMission= (select top(1) LogonTypeTaradod.ConvertedTypeTaradod
							FROM DeviceInfo INNER JOIN LogonTypeTaradod  ON DeviceInfo.Model = LogonTypeTaradod.DeviceModel
								where TraficID = @IDTraffic   and DeviceInfo.id=@DeviceId )

					Insert Into LogonPersonel
						([DateTimeLogM],[IDTraffic],[PersonNO],[DeviceId],[TrafficType],[TrafficTypeVacationOrMission],[TrafficName],PersonID,Calced, IsVirtual,[Guid],DeviceSerial,deviceNo,IsDeleted)
					Values
						(@DateTimeLogM,@IDTraffic,@PersonNO,@DeviceId,@TrafficType,@TrafficTypeVacationOrMission, @TrafficName,@PersonID,'False', @IsVirtual,@GUID,@DeviceSerial,@deviceNO,@IsDeleted)
					Select @ReferenceID = max(id) from LogonPersonel

					
					update person
						set sentToServerStatus = 0
						where id = @PersonID

				end
			else
			begin
				set @ReferenceID = @BeforIDForThisTaradod
			end
		end
	select * from LogonPersonel  where id = @ReferenceID
	--select @ReferenceID
	--Return @ReferenceID
End
GO

