create or Alter Procedure [dbo].[sp_LogonPersonel_UpdatePersonIds]
As
Begin
	update	dbo.[LogonPersonel]
		set	PersonID= HardwareCodeCus.PersonID 
			FROM HardwareCodeCus INNER JOIN
				 LogonPersonel ON HardwareCodeCus.HardwareCode = LogonPersonel.PersonNO AND HardwareCodeCus.DeviceId = LogonPersonel.DeviceId
	WHERE (LogonPersonel.PersonID is null)

	update LogonPersonel
		set DeviceNO= DeviceInfo.DeviceNO
			from DeviceInfo inner join LogonPersonel on DeviceInfo.id = LogonPersonel.DeviceId
	where LogonPersonel.DeviceNO is null or LogonPersonel.DeviceNO =0
End
GO

