create or Alter Procedure [dbo].[sp_LogonPersonel_SelectLastTaradod]
	@DeviceId smallint,
	@PersonNo int,
	@Count int,
	@Date datetime=null
As
Begin
	if (ISNULL( @date,'') ='')
		Select top (@Count) *
		From LogonPersonel
		where DeviceId = @DeviceId  and PersonNo=@PersonNo and IsDeleted = 0
		order by dateTimeLogM desc
	else
		Select top (@Count) *
		From LogonPersonel
		where DeviceId = @DeviceId  and PersonNo=@PersonNo and DateTimeLogM=@Date and IsDeleted = 0
End
GO

-- ==========================================================================================
create or alter Procedure [dbo].[sp_LogonPersonel_SelectTopLastTaradods]
@Count int
As
Begin
 SELECT
        temp_LogonPersonel.DateTimeLogM as DateTimeLogM,
        temp_LogonPersonel.TrafficType as TrafficType,
        DeviceInfo.DeviceName as DeviceName ,
        Person.FullName AS PersonFullName,
        Person.Id AS personId,
        temp_LogonPersonel.PersonNO as personNo,
        k.DateFinishM AS GharardadEndDate,
        k.GharardadStatus as GharardadStatus,
		GharardadStatus.Name as GharardadStatusName
    FROM 
    (
        SELECT TOP (@Count)
            PersonNO,
            DeviceId,
            DateTimeLogM,
            TrafficType
        FROM LogonPersonel
		where IsDeleted = 0
        ORDER BY DateTimeLogM DESC
    ) AS temp_LogonPersonel 
    INNER JOIN DeviceInfo 
        ON DeviceInfo.ID = temp_LogonPersonel.DeviceId
    LEFT JOIN HardwareCodeCus 
        ON HardwareCodeCus.HardwareCode = temp_LogonPersonel.PersonNO 
        AND DeviceInfo.ID = HardwareCodeCus.DeviceID
    LEFT JOIN Person 
        ON Person.Id = HardwareCodeCus.PersonID
    LEFT JOIN (   
				SELECT * FROM (
								SELECT 
								GharardadStatus,
									DateFinishM,
									personId,
								ROW_NUMBER() OVER (	PARTITION BY personId 	ORDER BY DateFinishM DESC) AS rn
								FROM Gharardad
							) AS t
				WHERE rn = 1
			 ) as k
        ON Person.Id = k.personId 
    LEFT JOIN GharardadStatus 
        ON k.GharardadStatus = GharardadStatus.ID
    WHERE 
        --PersonNO <> 1000 and  
		person.Id is not null
    ORDER BY 
        temp_LogonPersonel.DateTimeLogM DESC
End
Go
--============================================================================================
create or alter Procedure [dbo].[sp_LogonPersonel_SelectTopLastTaradodsBydeviceId]
@Count int, @deviceId int
As
Begin
 SELECT
        temp_LogonPersonel.DateTimeLogM as DateTimeLogM,
        temp_LogonPersonel.TrafficType as TrafficType,
        DeviceInfo.DeviceName as DeviceName ,
        Person.FullName AS PersonFullName,
        Person.Id AS personId,
        temp_LogonPersonel.PersonNO as personNo,
        k.DateFinishM AS GharardadEndDate,
        k.GharardadStatus as GharardadStatus,
		GharardadStatus.Name as GharardadStatusName
    FROM 
    (
        SELECT TOP (@Count)
            PersonNO,
            DeviceId,
            DateTimeLogM,
            TrafficType
        FROM LogonPersonel
		where IsDeleted = 0 and DeviceId=@deviceId
        ORDER BY DateTimeLogM DESC
    ) AS temp_LogonPersonel 
    INNER JOIN DeviceInfo 
        ON DeviceInfo.ID = temp_LogonPersonel.DeviceId
    LEFT JOIN HardwareCodeCus 
        ON HardwareCodeCus.HardwareCode = temp_LogonPersonel.PersonNO 
        AND DeviceInfo.ID = HardwareCodeCus.DeviceID
    LEFT JOIN Person 
        ON Person.Id = HardwareCodeCus.PersonID
    LEFT JOIN (   
				SELECT * FROM (
								SELECT 
								GharardadStatus,
									DateFinishM,
									personId,
								ROW_NUMBER() OVER (	PARTITION BY personId 	ORDER BY DateFinishM DESC) AS rn
								FROM Gharardad
							) AS t
				WHERE rn = 1
			 ) as k
        ON Person.Id = k.personId 
    LEFT JOIN GharardadStatus 
        ON k.GharardadStatus = GharardadStatus.ID
    WHERE 
        person.Id is not null
    ORDER BY 
        temp_LogonPersonel.DateTimeLogM DESC
End
Go
