create or Alter Procedure [dbo].[sp_LogonPersonel_Update]
	@ID int,
	@DateTimeLogM datetime,
	@IDTraffic bigint,
	@TrafficName nvarchar(50),
	@TrafficType smallint,
	@TrafficTypeVacationOrMission smallint,
	@Duration  smallint,
	@IsVirtual smallint
As
Begin
	declare @PersonId int

	select @PersonId=LogonPersonel.PersonId 
	from LogonPersonel
	where ID=@ID

	set @PersonId=ISNULL(@PersonId,0)

	Update dbo.LogonPersonel
	Set
		[DateTimeLogM] = @DateTimeLogM,
		[IDTraffic] = @IDTraffic,
		[TrafficType]=@TrafficType ,
		[TrafficTypeVacationOrMission]=@TrafficTypeVacationOrMission ,
		[TrafficName]=@TrafficName,
		[Duration]  = @Duration ,
		[IsVirtual] = @IsVirtual
	Where [ID] = @ID

	if(@PersonId>0)
		update Person
		set sentToServerStatus=0
		where ID=@PersonId
End
GO

