create or Alter Procedure [dbo].[SP_LogONPersonelByDate_SelectRow]
	@Date1 datetime,
	@Date2 datetime,
	@PersonID int = 0
As
Begin
	SELECT *
	FROM dbo.[LogonPersonel]
	where (@PersonID = 0 or [PersonID]=@PersonID) and ([DateTimeLogM] between @Date1 and @Date2) 
	order by [DateTimeLogM] asc
END

GO
-- ==========================================================================================
create or Alter Procedure [dbo].[SP_LogONPersonel_delete_repeatedTaradods]
As
Begin
	delete from [LogonPersonel] 
        where id in  
			( select id from 
				( 
					select Id, DateTimeLogM, LEFT(CONVERT(VARCHAR, [DateTimeLogM], 120), 16) as ddd, IDTraffic  , [LogonPersonel].PersonNO, PersonID
					, TrafficType,TrafficTypeVacationOrMission ,b.timex, b.cnt 
						,ROW_NUMBER() OVER(PARTITION BY [LogonPersonel].PersonNO, LEFT(CONVERT(VARCHAR, [DateTimeLogM], 120), 16) ORDER BY DateTimeLogM ) AS [Row] 
					from [LogonPersonel] 
					left outer join 
					( 
						select [PersonNO], timex, count(*) as cnt 
							from 
								( SELECT[PersonNO], LEFT(CONVERT(VARCHAR, [DateTimeLogM], 120), 16) as timex FROM[dbo].[LogonPersonel]  ) as a 
						group by personno, timex 
					--having count(timex) > 1 
					) as b 
					on[LogonPersonel].PersonNO = b.personno and  LEFT(CONVERT(VARCHAR, [LogonPersonel].[DateTimeLogM], 120), 16)= b.timex 
				) as c 
				where cnt >1 and [Row] > 1 
			)
END
GO
