create or Alter Procedure [dbo].[SP_LogoNPersonel_Update_MoveToNextDate]
As
Begin
	update [dbo].[LogonPersonel] set calced = 'false'
	delete from logonpersonel 
		where (right(LEFT(CONVERT(VARCHAR, [DateTimeLogM], 120), 19), 8) = '00:00:01'
		or right(LEFT(CONVERT(VARCHAR, [DateTimeLogM], 120), 19),8) = '23:59:59'
		or right(LEFT(CONVERT(VARCHAR, [DateTimeLogM], 120), 19),8) = '00:00:00')
		and [DateTimeLogM] > '2018-08-23'  and  IsVirtual in (3,4);
END
