create or Alter Procedure [dbo].[sp_LogUsers_Insert]
	@UserID int, 
	@DateM datetime, 
	@Description nvarchar(max), 
	@ActionTypeName  nvarchar(50), 
	@LogData nvarchar(max),
	@LogDataOld nvarchar(max),
	@LogDataNew nvarchar(max),
	@Refrence nvarchar(50)
As
Begin

delete from logusers where ActionTypeName = 'Not in CountDays' or ActionTypeName = 'FrmMain.ReceiveTaradodAsync'
	Insert Into LogUsers
		(UserID, DateM, [Description], LogData,[Refrence], ActionTypeName,LogDataOld,LogDataNew)
	Values
		(@UserID, @DateM, @Description, @LogData,@Refrence,@ActionTypeName,@LogDataOld,@LogDataNew)
	Select @@IDENTITY
	Return @@IDENTITY
End
GO
-- ==========================================================================================
create or Alter Procedure [dbo].[sp_LogUsers_SelectAll]
	@LstUsersID nvarchar(Max),
	@DateM1 Datetime,
	@DateM2 Datetime,
	@Desc nvarchar(500)
As
Begin
	if @LstUsersID = ''
		Select [dbo].[LogUsers].*, [dbo].[UserAttendance].[Name]
		From LogUsers 
		inner join [dbo].[UserAttendance]
			on [dbo].[LogUsers].userid = [dbo].[UserAttendance].ID
		where [ST]='true' and [DateM] between @DateM1 and @DateM2
			and (@Desc = '' or  [dbo].[UserAttendance].[Description] like @Desc)
		order by [DateM] desc
	else
		Select [dbo].[LogUsers].*, [dbo].[UserAttendance].[Name]
		From LogUsers 
		inner join [dbo].[UserAttendance]
			on [dbo].[LogUsers].userid = [dbo].[UserAttendance].ID
		inner join (select item from dbo.SplitStrings(@LstUsersID,',')) as a on dbo.LogUsers.[UserID] = cast(a.item as int) 
		where [ST]='true' and [DateM] between @DateM1 and @DateM2
			and (@Desc = '' or  [dbo].[UserAttendance].[Description] like @Desc)
		order by [DateM] desc
End

GO
