create or Alter  Procedure [dbo].[sp_MorakhasiDaily_Save]
	@DateM datetime,
	@PersonID int,
	@Desc nvarchar(500),
	@TypeID smallint
	--@TypeMorakhasiName nvarchar(50) = '',
	--@PersonCodeTafsil bigint =0,
	--@PersonFullName  nvarchar = '',
	--@HasHoghogh bit = false,
	--@HasMaliyat bit = true,
	--@HasBimeh bit

As
Begin
declare @temp table ( ID INT )
--آپدیت رکورد
			Update dbo.MorakhasiDaily
				Set
					 [Desc] = @Desc,
					 [TypeID] = @TypeID,
					 DateInserted=GETDATE()

					 OUTPUT INSERTED.ID into @temp
				Where [DateM]=@DateM and [PersonID]=@PersonID

				if(@@ROWCOUNT=0)
					begin
--درج رکورد			
						Insert Into MorakhasiDaily
						
								([DateM],[PersonID],[Desc],[TypeID])
								OUTPUT INSERTED.ID into @temp
						Values	(@DateM,@PersonID,@Desc,@TypeID)
					end

					
			update person
				set sentToServerStatus = 0
				where id = @PersonID

		select id from @temp

End
GO

