create or Alter Procedure [dbo].[sp_MorakhasiSaati_SelectAll]
	@personID int,
	@Date1 date,
	@Date2 date, 
	@TrafficType smallint = 0
As
Begin
		select  DateM,[PersonID], [VacationTime] as Duration 
			from [dbo].[ATT_TaradodDet]
			where ([dbo].[ATT_TaradodDet].DateM between @Date1 and @Date2) 
			and [VacationTime]>0
			and (@personID = 0 or PersonID = @personID )
		union
		select [DateTimeLogM] as DateM, PersonID, [Duration]
			from [dbo].[LogonPersonel]
			where (cast(DateTimeLogM as date) between @Date1 and @Date2) 
			and [Duration]>0 and (@TrafficType = 0 or [TrafficTypeVacationOrMission] = @TrafficType)
			and (@personID = 0 or PersonID = @personID )
	order by DateM 
End
GO
