create or Alter Procedure [dbo].[sp_OutputDevice_Save]
	@ID			int,
	@Name		nvarchar(500),
	@Seprator	nvarchar(50),
	@NextRecord nvarchar(50),
	@FormatType nvarchar(50),
	@enCoding	nvarchar(50),
	@PersonNO	smallint,
	@DateM		smallint,
	@DateSH		smallint,
	@DeviceNO	smallint,
	@Time	smallint,
	@Type	smallint,
	@ST		bit,
	@Header nvarchar(500),
	@HeaderLineNumber smallint
As
Begin
		update OutputDevice
				set [Name]=@Name,
					Seprator=@Seprator,
					NextRecord=@NextRecord,
					FormatType=@FormatType,
					[enCoding]=@enCoding,
					PersonNO=@PersonNO,
					DateM=@DateM,
					DateSH=@DateSH,
					DeviceNO=@DeviceNO,
					[Time]=@Time,
					[Type]=@Type,
					ST=@ST,
					Header=@Header,
					HeaderLineNumber = @HeaderLineNumber
				Where ID = @ID

		if @@rowcount = 0
		Insert Into OutputDevice
			([ID],[Name],[Seprator],[NextRecord],[FormatType],[enCoding],[PersonNO],[DateM],[DateSH],[DeviceNO],[Time],[Type],[ST],[Header], [HeaderLineNumber])
		Values
			(@ID,@Name,@Seprator,@NextRecord,@FormatType,@enCoding,@PersonNO,@DateM,@DateSH,@DeviceNO,@Time,@Type,@ST,@Header, @HeaderLineNumber)
End
GO
