-- ==========================================================================================
create or Alter Procedure [dbo].[sp_Person_HaveNotGharardad]
	@LogonPersonelIds nvarchar(100)
As
Begin
	Select a.id, a.FullName, a.CodeTafsil, a.CodeMoein
	from Person as a inner join
	(
		select id
		from [dbo].[Person]
		except 
		select PersonID
		from [dbo].[Gharardad]
	) as b on a.ID = b.ID inner join 
	HardwareCodeCus on a.id = HardwareCodeCus.PersonID inner join 
	logonpersonel on HardwareCodeCus.HardwareCode = logonpersonel.PersonNO inner join 
	(select item from dbo.SplitStrings(@LogonPersonelIds ,',')) as c on logonpersonel.ID = cast(c.item as int)
End
GO
-- ==========================================================================================
create or ALTER   Procedure [dbo].[sp_Person_Insert]
	@GroupID smallint,
	@TitleID smallint,
	@HID int,
	@HType smallint,
	@Code nvarchar(50),
	@Type smallint,
	@FullCode nvarchar(150),
	@Name nvarchar(50),
	@LatinFullName nvarchar(50),
	@Family nvarchar(50),
	@FullName nvarchar(200),
	@FatherName nvarchar(50),
	@DateMStartWork datetime,
	@DateMBirthday datetime,
	@CodeMeli char(10),
	@ZipCode char(10),
	@Adress nvarchar(300),
	@Mob1 char(11),
	@Mob2 char(11),
	@Tel1 char(11),
	@Tel2 char(11),
	@ST bit,
	@GUID nvarchar(max),
	@Pic image=null,
	@PicPath nvarchar(500)=null,
	@Description nvarchar(500)='',
	@NOBimeh nvarchar(20)='',
	@SodorSH nvarchar(30)='',
	@MTavalod nvarchar(30)='',
	@DateMFinishW datetime=getdate,
	@CodeTafsil bigint,
	@CodeMoein bigint,
	@EisarID smallint=0,
 	@SHSH nvarchar(15)='',
	@SerialSH nvarchar(15)='',
	@Jensiat smallint=0,
	@MadrakTahsili nvarchar(100)='',
	@UserName nvarchar(100)='',
	@sentToServerStatus smallint = 0,
	@HashPassword binary(500),
	@DepartmentGuid uniqueidentifier=null
As
Begin
	if ( ISNULL(@GUID,'')='')
	begin 
		set @GUID=NEWID()
	end
	declare @sw int
	select @sw = ID  FROM [dbo].[PersonGroup] where st = 1 and id= @GroupID
	if (isnull(@sw,0)=0)
	begin
		set @GroupID = ( select top (1) [ID] from [dbo].[PersonGroup] Where st = 1 )
	end
		if (isnull(@GroupID,0) <> 0) 
		begin
			Insert Into Person
				([GroupID],[TitleID],[HID],[HType],[Code],[Type],[FullCode],[Name],[LatinFullName],[Family],[FullName],[FatherName],[DateMStartWork],[DateMBirthday],[CodeMeli],[ZipCode],[Adress],[Mob1],[Mob2],[Tel1],[Tel2],[ST],[GUID],[Pic],[PicPath],[Description],[NOBimeh],[SodorSH],[MTavalod],[DateMFinishW],[CodeTafsil],[CodeMoein],[EisarID],[SHSH],[SerialSH],[Jensiat],[MadrakTahsili],[UserName],[HashPassword],[sentToServerStatus],[DepartmentGuid])
			Values
				(@GroupID,@TitleID,  @HID, @HType, @Code, @Type, @FullCode, @Name,@LatinFullName, @Family, @FullName, @FatherName, @DateMStartWork, @DateMBirthday, @CodeMeli, @ZipCode, @Adress, @Mob1, @Mob2, @Tel1, @Tel2, @ST, @GUID, @Pic, @PicPath, @Description, @NOBimeh, @SodorSH, @MTavalod, @DateMFinishW, @CodeTafsil, @CodeMoein, @EisarID, @SHSH, @SerialSH, @Jensiat, @MadrakTahsili,@UserName,@HashPassword,@sentToServerStatus,@DepartmentGuid)
		end
	Select @@IDENTITY
	Return @@IDENTITY
End
GO
-- ==========================================================================================
create or Alter Procedure [dbo].[sp_Person_LoadEnrollData]
	@personIDs nvarchar(max)
As
Begin
	if @personIDs = ''
	begin
		Select ID, [EnrollData]
 		From Person 
		where [ST]='true'
		order by ID
	end
	else
	begin
		Select ID, [EnrollData]
		From Person inner join 
		(select item from dbo.SplitStrings(@personIDs,',')) as a on dbo.Person.ID = cast(a.item as int) 
		where [ST]='true' 
		order by ID
	end
End
GO
-- ==========================================================================================
create or Alter Procedure [dbo].[sp_Person_SaveEnrollData]
	@ID int,
 	@serializeObj varbinary(max)
As
Begin
	update [dbo].[Person]
		set [EnrollData] = @serializeObj
		where [ID] = @ID
End
GO
-- ==========================================================================================
create or Alter Procedure [dbo].[sp_Person_SelectAll]
	@personIDs nvarchar(Max)
As
Begin
	if @personIDs = ''
	begin
		Select *
 		From Person 
		--where [ST]='true' 
		order by [family] asc,[name] asc
	end
	else
	begin
		Select *
		From Person inner join 
		(select item from dbo.SplitStrings(@personIDs,',')) as a on dbo.Person.ID = cast(a.item as int) 
		--where [ST]='true' 
			order by [family] asc,[name] asc
	end
End

GO
-- ==========================================================================================
create or Alter Procedure [dbo].[sp_Person_SelectAll_BySentToServerStatus]
	@personIDs nvarchar(Max),
	@sentToServerStatus smallint

As
Begin
	if @personIDs = ''
	begin
		Select *
 		From Person 
		where [ST]='true' and [sentToServerStatus] = @sentToServerStatus  and username <> '' and HashPassword is not null and LEN(HashPassword) >1
		order by [family] asc,[name] asc
	end
	else
	begin
		Select *
		From Person inner join 
		(select item from dbo.SplitStrings(@personIDs,',')) as a on dbo.Person.ID = cast(a.item as int) 
		where [ST]='true'  and [sentToServerStatus] = @sentToServerStatus and username <> '' and HashPassword is not null and LEN(HashPassword) >1
			order by [family] asc,[name] asc
	end
End

GO
