create or ALTER   Procedure [dbo].[sp_Person_Update]
	@ID int,
	@GroupID smallint,
	@TitleID smallint,
	@HID int,
	@HType smallint,
	@Code nvarchar(50),
	@Type smallint,
	@FullCode nvarchar(150),
	@Name nvarchar(50),
	@LatinFullName nvarchar(50),
	@Family nvarchar(50),
	@FullName nvarchar(200),
	@FatherName nvarchar(50),
	@DateMStartWork datetime,
	@DateMBirthday datetime,
	@CodeMeli char(10),
	@ZipCode char(10),
	@Adress nvarchar(300),
	@Mob1 char(11),
	@Mob2 char(11),
	@Tel1 char(11),
	@Tel2 char(11),
	@ST bit,
	@GUID uniqueidentifier,
	@Pic image=null,
	@PicPath nvarchar(500)=null,
	@Description nvarchar(500)='',
	@NOBimeh nvarchar(20)='',
	@SodorSH nvarchar(30)='',
	@MTavalod nvarchar(30)='',
	@DateMFinishW datetime=getdate,
	@CodeTafsil bigint,
	@CodeMoein bigint,
	@EisarID smallint=0,
	@SHSH nvarchar(15)='',
	@SerialSH nvarchar(15)='',
	@Jensiat smallint=0,
	@MadrakTahsili nvarchar(100)='',
	@UserName nvarchar(100)='',
	@HashPassword binary(500),
	@sentToServerStatus smallint=0,
	@DepartmentGuid uniqueidentifier=null
As
Begin
declare @sw int
	select @sw = ID  FROM [dbo].[PersonGroup] where st = 1 and id= @GroupID
	if (isnull(@sw,0)=0)
	begin
		set @GroupID = ( select top (1) [ID] from [dbo].[PersonGroup] Where st = 1 )
	end
		if (isnull(@GroupID,0) <> 0) 
		begin
		Update dbo.Person
		Set
			[GroupID] = @GroupID,
			[TitleID] = @TitleID,
			[HID] = @HID,
			[HType] = @HType,
			[Code] = @Code,
			[Type] = @Type,
			[FullCode] = @FullCode,
			[Name] = @Name,
			[LatinFullName] = @LatinFullName,
			[Family] = @Family,
			[FullName] = @FullName,
			[FatherName] = @FatherName,
			[DateMStartWork] = @DateMStartWork,
			[DateMBirthday] = @DateMBirthday,
			[CodeMeli] = @CodeMeli,
			[ZipCode] = @ZipCode,
			[Adress] = @Adress,
			[Mob1] = @Mob1,
			[Mob2] = @Mob2,
			[Tel1] = @Tel1,
			[Tel2] = @Tel2,
			[NOBimeh]  = @NOBimeh ,
			[ST] = @ST,
			[GUID] = @GUID,
			[Pic] = @Pic,
			[PicPath] = @PicPath,
			[Description] = @Description,
			[SodorSH] = @SodorSH,
			[MTavalod] = @MTavalod,
			[DateMFinishW] = @DateMFinishW,
			[CodeTafsil] = @CodeTafsil,
			[CodeMoein] = @CodeMoein,
			[EisarID]=@EisarID,
 			[SHSH]=@SHSH,
			[SerialSH]=@SerialSH, 
			[Jensiat]=@Jensiat,
			[MadrakTahsili]=@MadrakTahsili,
			[Modified]=getdate(),
			[sentToServerStatus]=@sentToServerStatus,
			[UserName]=@UserName,
			[HashPassword]=@HashPassword,
			[DepartmentGuid]=@DepartmentGuid
		Where [ID] = @ID
	end
End
GO
