create or Alter Procedure [dbo].[sp_PersonGroup_Distinct]
As
Begin
      declare @cnt int
  set @cnt = ( select count(code) from [PersonGroup] where code =1 and name =N'پرسنل')
  if( @cnt>1)
  begin
		update Person set GroupID=1 where ID in ( select ID from [PersonGroup] where code =1 and name =N'پرسنل' and id>1 )
		delete from [PersonGroup] where code =1 and name =N'پرسنل' and id>1
	end
End
GO
