create or Alter Procedure [dbo].[sp_ReportGeneratorHozor_Insert]
	@ID int,
	@Title nvarchar(MAX),
	@Description nvarchar(MAX),
	@SQLQuery nvarchar(MAX),
	@RPT nvarchar(MAX)
As
Begin
	Insert Into ReportGeneratorHozor
		([ID],[Title],[Description],[SQLQuery],[RPT])
	Values
		(@ID,@Title,@Description,@SQLQuery,@RPT)
END
GO
-- ==========================================================================================
create or Alter Procedure [dbo].[sp_ReportGeneratorHozor_Save]
	@ID int,
	@Title nvarchar(MAX),
	@Description nvarchar(MAX),
	@SQLQuery nvarchar(MAX),
	@RPT nvarchar(MAX)
As
Begin
--report by user
	if(@ID=0)
	begin
		--insert user report
		select @ID=max(ID) from ReportGeneratorHozor
		set @ID=isnull(@ID,0)

		if (@ID<10000)
			set @ID=10000
		set @ID=@ID+1
		exec dbo.sp_ReportGeneratorHozor_Insert @ID,@Title,@Description,@SQLQuery,@RPT
	end
	else if(@ID>10000)
	begin
		  if ((select count(*) from dbo.ReportGeneratorHozor where ID=@ID)>0) --Update User Report
			exec dbo.sp_ReportGeneratorHozor_Update @ID,@Title,@Description,@SQLQuery,@RPT
		else 
			exec dbo.sp_ReportGeneratorHozor_Insert @ID,@Title,@Description,@SQLQuery,@RPT
	end
	else if (@ID<=10000)
	begin
		if((select count(*) from dbo.ReportGeneratorHozor where ID=@ID)>0) --Update System Report
			exec dbo.sp_ReportGeneratorHozor_Update @ID,@Title,@Description,@SQLQuery,@RPT
		else -- Insert System Report
			exec dbo.sp_ReportGeneratorHozor_Insert @ID,@Title,@Description,@SQLQuery,@RPT			
	end
	select @ID
	return @ID
END
GO
