create or Alter PROCEDURE [dbo].[sp_SettingAttendance_SaveValue] 
	@Name nvarchar(200),
	@UserID int,
	@Val nvarchar(MAX)
AS
BEGIN
	declare @Count int
	--execute @R=[dbo].[sp_SettingAttendance_SelectRow]@Name
	select @count=count(*)
	from SettingAttendance
	where [Name]=@Name and UserID=@UserID
	set @count=isnull(@count,0)

 	if(@count=0)
	begin
		--Insert Setting
		Insert Into SettingAttendance
			([Name],[UserID],[Val])
		Values (@Name,@UserID,@Val)
	end
	else
	begin
		--Update Setting
		Update dbo.SettingAttendance
		Set [Val] = @Val
		Where [Name] = @Name and [UserID] = @UserID
	end
END
GO
