create or Alter Procedure [dbo].[sp_ShiftDet_Save]
	@ShiftID smallint,
	@ShiftCodingID smallint,
	@Sat bit,
	@Sun bit,
	@Mon bit,
	@Tue bit,
	@Wed bit,
	@Tur bit,
	@Fri bit,
	@FriType smallint,
	@DateStartM	  datetime=getdate ,
    @DateFinishM datetime=getdate,
	@Description nvarchar(MAX)
	
As
Begin
	declare @sw int
	select @sw = [ShiftID]
	from [dbo].[ShiftDet]
	Where [ShiftID] = @ShiftID and [ShiftCodingID] = @ShiftCodingID and [DateStartM] = @DateStartM
	if (isnull(@sw,0)=0)
	begin
	select @sw = [ID]
		from [dbo].[ShiftCodeing]
		Where [ID] = @ShiftCodingID

		if (isnull(@sw,0) <> 0) 
		begin
			Insert Into [dbo].ShiftDet
				([ShiftID], [ShiftCodingID],[Sat],[Sun],[Mon],[Tue],[Wed],[Tur],[Fri],[FriType],[Description],[DateFinishM],[DateStartM])
			Values
				(@ShiftID, @ShiftCodingID, @Sat, @Sun, @Mon, @Tue, @Wed, @Tur, @Fri,@FriType, @Description, @DateFinishM, @DateStartM)
			Select @@IDENTITY
			Return @@IDENTITY
		end
	end
	else
	Begin
		Update [dbo].ShiftDet
		Set [Sat] = @Sat
			,[Sun] = @Sun
			,[Mon] = @Mon
			,[Tue] = @Tue
			,[Wed] = @Wed
			,[Tur] = @Tur
			,[Fri] = @Fri
			,[FriType] = @FriType
			,[Description] = @Description
			,[DateFinishM] = @DateFinishM
			,[DateStartM] = @DateStartM
		Where [ShiftID] = @ShiftID and [ShiftCodingID] = @ShiftCodingID and [DateStartM] = @DateStartM
	End
End
GO
