create or Alter Procedure [dbo].[SP_ShiftDetView_SelectAll]
As
Begin
		SELECT	Gharardad.ID as GharardadID,[dbo].[ShiftDet].ShiftCodingID,Gharardad.[DateStartM] as GharardadDateStartM, Gharardad.[DateFinishM] as GharardadDateFinishM, [dbo].[ShiftDet].DateStartM as ShiftDateStartM, [dbo].[ShiftDet].DateFinishM as ShiftDateFinishM, Sat, Sun, Mon, Tue, Wed, Tur, Fri
				,FriType,STTatili as Shift_Tatital,[dbo].[ShiftCodeing].*,Gharardad.ShiftID
		FROM	[ShiftDet] inner join Gharardad on Gharardad.ShiftID=[ShiftDet].[ShiftID] 
				inner join Shifts on Shifts.ID=Gharardad.ShiftID
				inner join [dbo].[ShiftCodeing] on [dbo].[ShiftCodeing].[ID] = [dbo].[ShiftDet].[ShiftCodingID]
		union
		SELECT	Gharardad.ID as GharardadID,[dbo].[ShiftProgrammableDet].ShiftCodingID,Gharardad.[DateStartM] as GharardadDateStartM, Gharardad.[DateFinishM] as GharardadDateFinishM,
				[dbo].[ShiftProgrammableDet].DateStartM as ShiftDateStartM, [dbo].[ShiftProgrammableDet].DateFinishM as ShiftDateFinishM
				,CAST('True' as bit) as Sat, CAST('True' as bit) as Sun, CAST('True' as bit) as Mon, CAST('True' as bit) as Tue, CAST('True' as bit) as Wed
				, CAST('True' as bit) as Tur, CAST('True' as bit) as Fri,1 as FriType,CAST('FALSE' as bit) as Shift_Tatital
				,[dbo].[ShiftCodeing].*,Gharardad.ShiftID
		FROM	[dbo].[ShiftProgrammableDet] inner join 
				[dbo].[Gharardad] on [dbo].[Gharardad].[ID] = [dbo].[ShiftProgrammableDet].[GharardadID] inner join 
				[dbo].[ShiftCodeing] on [dbo].[ShiftCodeing].[ID] = [dbo].[ShiftProgrammableDet].[ShiftCodingID]
End
GO
-- ==========================================================================================
create or Alter Procedure [dbo].[SP_ShiftDetView_SelectRowByDate]
	@Date datetime,
	@GharardadID int
As
Begin
	declare @Dow smallint;
	set @Dow=DATEPART(WEEKDAY,@Date) 
	IF Not EXISTS ( select id from [dbo].[Gharardad] where ID = @GharardadID and [ShiftID] = -1)
	begin
		SELECT	[dbo].[ShiftDet].ShiftCodingID, [dbo].[ShiftDet].DateStartM, [dbo].[ShiftDet].DateFinishM, Sat, Sun, Mon, Tue, Wed, Tur, Fri,FriType
			,STTatili as Shift_Tatital,STRasmi as Holidays_Tatil,[dbo].[ShiftCodeing].*,Gharardad.ShiftID
		FROM	[ShiftDet] inner join Gharardad on Gharardad.ShiftID=[ShiftDet].[ShiftID] 
				inner join Shifts on Shifts.ID=Gharardad.ShiftID
				inner join Holiday on cast(Holiday.DateM as date)=CAST(@Date as date)
				inner join [dbo].[ShiftCodeing] on [dbo].[ShiftCodeing].[ID] = [dbo].[ShiftDet].[ShiftCodingID]
		where	Gharardad.ID=@GharardadID and 
				(@Date between Gharardad.[DateStartM] and Gharardad.[DateFinishM]) and
				(@Date between ShiftDet.[DateStartM] and ShiftDet.[DateFinishM]) and 
				(	
					(sat='true' and @Dow=7) or
					(Fri='true' and @Dow=6) or
					(tur='true' and @Dow=5) or
					(Wed='true' and @Dow=4) or
					(tue='true' and @Dow=3) or
					(Mon='true' and @Dow=2) or
					(sun='true' and @Dow=1) 
				)
	end
	else
	begin
		SELECT distinct	[dbo].[ShiftProgrammableDet].ShiftCodingID, [dbo].[ShiftProgrammableDet].DateStartM, [dbo].[ShiftProgrammableDet].DateFinishM
		,CAST('True' as bit) as Sat, CAST('True' as bit) as Sun, CAST('True' as bit) as Mon, CAST('True' as bit) as Tue, CAST('True' as bit) as Wed
		, CAST('True' as bit) as Tur, CAST('True' as bit) as Fri,dbo.ShiftProgrammableDet.FriDayType as FriType,WorkOnHolidays as Shift_Tatital,STRasmi as Holidays_Tatil ,[dbo].[ShiftCodeing].*,Gharardad.ShiftID
		FROM	[dbo].[ShiftProgrammableDet] inner join 
			[dbo].[Gharardad] on [dbo].[Gharardad].[ID] = [dbo].[ShiftProgrammableDet].[GharardadID] inner join 
			[dbo].[Holiday] on cast(Holiday.DateM as date)=CAST(@Date as date) inner join 
			[dbo].[ShiftCodeing] on [dbo].[ShiftCodeing].[ID] = [dbo].[ShiftProgrammableDet].[ShiftCodingID] 
			inner join
			[ShiftDet] on [dbo].[ShiftCodeing].[ID] = [dbo].[ShiftDet].[ShiftCodingID]
			--and ShiftDet.[Description]=ShiftProgrammableDet.[Desc]
		where Gharardad.ID=@GharardadID and 
				(@Date between Gharardad.[DateStartM] and Gharardad.[DateFinishM]) and
				(@Date between [dbo].[ShiftProgrammableDet].[DateStartM] and [dbo].[ShiftProgrammableDet].[DateFinishM]) 
		
		--union
		
		--SELECT distinct	[dbo].[ShiftProgrammableDet].ShiftCodingID, [dbo].[ShiftProgrammableDet].DateStartM, [dbo].[ShiftProgrammableDet].DateFinishM
		--,isnull( shiftdet.Sat, 1) as Sat, isnull( shiftdet.Sun, 1) as Sun,isnull( shiftdet.Mon, 1) as Mon,isnull( shiftdet.Tue, 1) as Tue,isnull( shiftdet.Wed, 1) as Wed,isnull( shiftdet.Tur, 1) as Tur,isnull( shiftdet.Fri, 1) as Fri
		--,isnull(ShiftDet.FriType, 1) as FriType,WorkOnHolidays as Shift_Tatital,STRasmi as Holidays_Tatil ,[dbo].[ShiftCodeing].*,Gharardad.ShiftID
		--FROM	[dbo].[ShiftProgrammableDet] inner join 
		--	[dbo].[Gharardad] on [dbo].[Gharardad].[ID] = [dbo].[ShiftProgrammableDet].[GharardadID] inner join 
		--	[dbo].[Holiday] on cast(Holiday.DateM as date)=CAST(@Date as date) inner join 
		--	[dbo].[ShiftCodeing] on [dbo].[ShiftCodeing].[ID] = [dbo].[ShiftProgrammableDet].[ShiftCodingID] 
		--	left join	[ShiftDet] on [dbo].[ShiftCodeing].[ID] = [dbo].[ShiftDet].[ShiftCodingID] and ShiftDet.[Description]=ShiftProgrammableDet.[Desc]
		--where Gharardad.ID=@GharardadID and 
		--		(@Date between Gharardad.[DateStartM] and Gharardad.[DateFinishM]) and
		--		(@Date between [dbo].[ShiftProgrammableDet].[DateStartM] and [dbo].[ShiftProgrammableDet].[DateFinishM]) 

	end
END	
GO
