create or Alter Procedure [dbo].[SP_ShiftDetView_GetAllByDate]
	@Date datetime
	,@GharardadId int
As
Begin
--declare @Date datetime;
--set @Date = '2025/04/09 00:00:00'
	declare @Dow smallint;
	set @Dow=DATEPART(WEEKDAY,@Date) 
			SELECT distinct	[dbo].[ShiftDet].ShiftCodingID, [dbo].[ShiftDet].DateStartM, [dbo].[ShiftDet].DateFinishM, Sat, Sun, Mon, Tue, Wed, Tur, Fri,FriType
			,STTatili as Shift_Tatital,STRasmi as Holidays_Tatil,[dbo].[ShiftCodeing].*,Gharardad.ShiftID,Gharardad.ID
		FROM	[ShiftDet] inner join Gharardad on Gharardad.ShiftID=[ShiftDet].[ShiftID] 
				inner join Shifts on Shifts.ID=Gharardad.ShiftID
				inner join Holiday on cast(Holiday.DateM as date)=CAST(@Date as date)
				inner join [dbo].[ShiftCodeing] on [dbo].[ShiftCodeing].[ID] = [dbo].[ShiftDet].[ShiftCodingID]
		where	(@Date between Gharardad.[DateStartM] and Gharardad.[DateFinishM]) and
				(@Date between ShiftDet.[DateStartM] and ShiftDet.[DateFinishM]) and 
				(	
					(sat='true' and @Dow=7) or
					(Fri='true' and @Dow=6) or
					(tur='true' and @Dow=5) or
					(Wed='true' and @Dow=4) or
					(tue='true' and @Dow=3) or
					(Mon='true' and @Dow=2) or
					(sun='true' and @Dow=1) 
				) and
				Gharardad.ID = @GharardadId
				
	union
		SELECT distinct	[dbo].[ShiftProgrammableDet].ShiftCodingID, [dbo].[ShiftProgrammableDet].DateStartM, [dbo].[ShiftProgrammableDet].DateFinishM
		,CAST('True' as bit) as Sat, CAST('True' as bit) as Sun, CAST('True' as bit) as Mon, CAST('True' as bit) as Tue, CAST('True' as bit) as Wed
		, CAST('True' as bit) as Tur, CAST('True' as bit) as Fri,dbo.ShiftProgrammableDet.FriDayType as FriType,WorkOnHolidays as Shift_Tatital,STRasmi as Holidays_Tatil ,[dbo].[ShiftCodeing].*,Gharardad.ShiftID,Gharardad.ID
		FROM	[dbo].[ShiftProgrammableDet] inner join 
			[dbo].[Gharardad] on [dbo].[Gharardad].[ID] = [dbo].[ShiftProgrammableDet].[GharardadID] inner join 
			[dbo].[Holiday] on cast(Holiday.DateM as date)=CAST(@Date as date) inner join 
			[dbo].[ShiftCodeing] on [dbo].[ShiftCodeing].[ID] = [dbo].[ShiftProgrammableDet].[ShiftCodingID] 
			inner join
			[ShiftDet] on [dbo].[ShiftCodeing].[ID] = [dbo].[ShiftDet].[ShiftCodingID]
			--and ShiftDet.[Description]=ShiftProgrammableDet.[Desc]
		where (@Date between Gharardad.[DateStartM] and Gharardad.[DateFinishM]) and
				(@Date between [dbo].[ShiftProgrammableDet].[DateStartM] and [dbo].[ShiftProgrammableDet].[DateFinishM]) and
				Gharardad.ID = @GharardadId
END	
GO
