create or Alter Procedure [dbo].[sp_ShiftProgrammableDet_Save]
	@GharardadID int,
	@ShiftCodingID smallint,
	@DateStartM	  datetime=getdate ,
    @DateFinishM datetime=getdate,
	@Description nvarchar(MAX),
	@WorkOnHolidays bit,
	@FriDayType smallint
	
As
Begin
	declare @sw int
	select @sw = [GharardadID]
	from [dbo].[ShiftProgrammableDet]
	Where [GharardadID] = @GharardadID and [ShiftCodingID] = @ShiftCodingID and [DateStartM] = @DateStartM
	if (isnull(@sw,0)=0)
	begin
		select @sw = [ID]
		from [dbo].[Gharardad]
		Where [ID] = @GharardadID

		if (isnull(@sw,0) <> 0) 
			begin
				Insert Into ShiftProgrammableDet
					([GharardadID], [ShiftCodingID],[Desc],[DateStartM],[DateFinishM], WorkOnHolidays,FriDayType)
				Values
					(@GharardadID, @ShiftCodingID, @Description, @DateStartM, @DateFinishM, @WorkOnHolidays,@FriDayType)
				Select @@IDENTITY
				Return @@IDENTITY
			end
	end
	else
	Begin
		Update ShiftProgrammableDet
		Set  [Desc] = @Description
			,[DateFinishM] = @DateFinishM
			,[DateStartM] = @DateStartM
			,[WorkOnHolidays] = @WorkOnHolidays
			,[FriDayType]=@FriDayType
		Where [GharardadID] = @GharardadID and [ShiftCodingID] = @ShiftCodingID
	End
End
GO
