create or Alter Procedure [dbo].[sp_Shifts_Insert]
	@Name nvarchar(250),
	@Code nvarchar(50),
	@Description nvarchar(MAX),
	@ST bit,
	@STTatili bit,
	@PackageType [smallint] ,
	@Periodic [smallint] ,
	@PackageGuid [uniqueidentifier] 

As
Begin
	Insert Into Shifts
		([Name],[Code],[Description],[ST],[STTatili]
		,[PackageType],[Periodic],[PackageGuid])
	Values
		(@Name, @Code, @Description, @ST, @STTatili
		,@PackageType,@Periodic, @PackageGuid)
	Select @@IDENTITY
	Return @@IDENTITY
End
GO
-- ==========================================================================================
create or Alter Procedure [dbo].[sp_Shifts_SelectAll]
	@ST bit='true',
	@PackageType smallint
As
Begin
	if(@PackageType = 20)
		Select * From Shifts where [ST]=@ST and  isnull(PackageType,0) < @PackageType
	else
		if(@PackageType = 50)
		Select * From Shifts where [ST]=@ST and isnull(PackageType,0) > @PackageType
	else
		if(@PackageType = 100)
		Select * From Shifts where [ST]=@ST 
	else
		Select * From Shifts where [ST]=@ST And ID > 0 and isnull(PackageType,0) = @PackageType
End
GO
-- ==========================================================================================
create or Alter Procedure [dbo].[sp_Shifts_SelectRow]
	@ID smallint
As
Begin
	Select *
	From Shifts
	Where [ID] = @ID
End
GO
