create or Alter Procedure [dbo].[sp_Shifts_ShiftViewModel]
	@ID smallint
as
begin
	SELECT dbo.Shifts.[Name]
		, dbo.Shifts.Code
		, dbo.Shifts.[Description]
		, dbo.Shifts.ST
		, dbo.Shifts.STTatili
		, dbo.Shifts.Periodic
		, dbo.Shifts.PackageGuid
		, dbo.Shifts.PackageType
		, dbo.ShiftDet.ShiftID
		, dbo.ShiftDet.ShiftCodingID
		, dbo.ShiftDet.DateStartM
		, dbo.ShiftDet.DateFinishM
		, dbo.ShiftDet.Sat
		, dbo.ShiftDet.Sun
		, dbo.ShiftDet.Mon
		, dbo.ShiftDet.Tue
		, dbo.ShiftDet.Wed
		, dbo.ShiftDet.Fri
		, dbo.ShiftDet.FriType
		, dbo.ShiftDet.Tur
		, dbo.ShiftCodeing.H1
		, dbo.ShiftCodeing.M1
		, dbo.ShiftCodeing.H2
		, dbo.ShiftCodeing.M2
		, dbo.ShiftCodeing.NextDay
		, dbo.ShiftCodeing.CalcEnteghalInSrcDate
		, dbo.ShiftCodeing.TypeShift
	FROM dbo.Shifts INNER JOIN
		dbo.ShiftDet ON dbo.Shifts.ID = dbo.ShiftDet.ShiftID INNER JOIN
		dbo.ShiftCodeing ON dbo.ShiftDet.ShiftCodingID = dbo.ShiftCodeing.ID
	Where dbo.Shifts.[ID] = @ID
End
GO
-- ==========================================================================================
create or Alter Procedure [dbo].[sp_Shifts_ShiftViewModelAll]
	@PackageType smallint
as
begin
	SELECT dbo.Shifts.[Name]
		, dbo.Shifts.Code
		, dbo.Shifts.[Description]
		, dbo.Shifts.ST
		, dbo.Shifts.STTatili
		, dbo.Shifts.Periodic
		, dbo.Shifts.PackageGuid
		, dbo.Shifts.PackageType
		, dbo.ShiftDet.ShiftID
		, dbo.ShiftDet.ShiftCodingID
		, dbo.ShiftDet.DateStartM
		, dbo.ShiftDet.DateFinishM
		, dbo.ShiftDet.Sat
		, dbo.ShiftDet.Sun
		, dbo.ShiftDet.Mon
		, dbo.ShiftDet.Tue
		, dbo.ShiftDet.Wed
		, dbo.ShiftDet.Fri
		, dbo.ShiftDet.FriType
		, dbo.ShiftDet.Tur
		, dbo.ShiftCodeing.H1
		, dbo.ShiftCodeing.M1
		, dbo.ShiftCodeing.H2
		, dbo.ShiftCodeing.M2
		, dbo.ShiftCodeing.NextDay
		, dbo.ShiftCodeing.CalcEnteghalInSrcDate
		, dbo.ShiftCodeing.TypeShift
	FROM dbo.Shifts INNER JOIN
		dbo.ShiftDet ON dbo.Shifts.ID = dbo.ShiftDet.ShiftID INNER JOIN
		dbo.ShiftCodeing ON dbo.ShiftDet.ShiftCodingID = dbo.ShiftCodeing.ID
	Where dbo.Shifts.ST= 1 and (
								(@PackageType = 50 and dbo.Shifts.PackageType >=50) --فقط همه پکیج ها
								or @PackageType = 100 --همه شیفتها و پکیج ها
								or dbo.Shifts.PackageType = @PackageType --فقط پکیج خاص
								)
End
GO
