create or Alter Procedure [dbo].[sp_STTatilShift_Calc]
	@PersonNO int,
	@DeviceId int
As
Begin
SELECT dbo.Shifts.STTatili
FROM dbo.Shifts INNER JOIN
 dbo.Gharardad ON dbo.Shifts.ID = dbo.Gharardad.ShiftID INNER JOIN
 dbo.HardwareCodeCus ON dbo.Gharardad.PersonID = dbo.HardwareCodeCus.PersonID
WHERE (dbo.HardwareCodeCus.HardwareCode = @PersonNO) AND (dbo.HardwareCodeCus.DeviceID = @DeviceId)
End
GO
