create or Alter Procedure [dbo].[sp_TaxTable_Insert]
	@StartDateM [datetime],
	@EndDateM [datetime],
	@Year [smallint],
	@FromPrice   decimal(18, 3),
	@ToPrice   decimal(18, 3),
	@TaxPercentage   decimal(18, 3),
	@InitialValue   decimal(18, 3),
	@Description [nvarchar](max)
As
Begin
delete from TaxTable
		where [FromPrice]=@FromPrice  and [Year]=@Year

	Insert Into TaxTable
		([StartDateM], [EndDateM], [Year], [FromPrice], [ToPrice], [TaxPercentage], [InitialValue], [Description])
	Values
		(@StartDateM, @EndDateM, @Year, @FromPrice, @ToPrice, @TaxPercentage, @InitialValue, @Description)

	Select @@IDENTITY
	Return @@IDENTITY

End
GO
