create or Alter Procedure [dbo].sp_LogonPersonel_SelectBySmsRefrenced
	@fromDate datetime,
	@Count int
As
Begin
	Select	top(@count) *
	From	LogonPersonel WITH (NOLOCK)
	where	IsDeleted = 0 and
			DateTimeLogM>=@fromDate AND 
			isnull(PersonID,0)>0 and 
			ISNULL(SmsrefrenceIDs,'')=''
	order by newId()
End
go

