create or Alter Procedure [dbo].[sp_tblEnroll_Save]
	@EMachineNumber int,
	@EnrollNumber int,
	@FingerNumber int,
	@Privilige int,
	@Password1 int,
	@FPData varbinary(MAX),
	@CompanyName nvarchar(50)
As
Begin
		Update dbo.tblEnroll
		Set
			EMachineNumber = @EMachineNumber,
			EnrollNumber = @EnrollNumber,
			FingerNumber = @FingerNumber,
			Privilige = @Privilige,
			Password1 = @Password1,
			FPData = @FPData,
			CompanyName=@CompanyName
		Where EMachineNumber = @EMachineNumber
			and EnrollNumber=@EnrollNumber
			and FingerNumber=@FingerNumber

	if @@rowcount = 0

		Insert Into tblEnroll
				(EMachineNumber,EnrollNumber,FingerNumber,Privilige,Password1,FPData,CompanyName)
			Values
				(@EMachineNumber, @EnrollNumber, @FingerNumber, @Privilige, @Password1, @FPData,@CompanyName)

	Select @@IDENTITY
	Return @@IDENTITY

End
GO
-- ==========================================================================================
create or Alter Procedure [dbo].[sp_tblEnroll_select]
	@EMachineNumber int,
	@EnrollNumbers nvarchar(Max)
As
Begin
	if @EMachineNumber<=0 and @EnrollNumbers = ''
		select [EMachineNumber],[EnrollNumber],[FingerNumber],[Privilige],[Password1],[FPData],[CompanyName] from dbo.tblEnroll

	else if @EMachineNumber>0 and @EnrollNumbers <> ''
		select [EMachineNumber],[EnrollNumber],[FingerNumber],[Privilige],[Password1],[FPData],[CompanyName] from dbo.tblEnroll
				INNER JOIN (select item from dbo.SplitStrings(@EnrollNumbers,',')) as a on dbo.tblEnroll.EnrollNumber = cast(a.item as int)
				Where EMachineNumber = @EMachineNumber

		else if @EnrollNumbers = ''
			select [EMachineNumber],[EnrollNumber],[FingerNumber],[Privilige],[Password1],[FPData],[CompanyName] from dbo.tblEnroll
				Where EMachineNumber = @EMachineNumber
			else 
				select [EMachineNumber],[EnrollNumber],[FingerNumber],[Privilige],[Password1],[FPData],[CompanyName] from dbo.tblEnroll
						INNER JOIN (select item from dbo.SplitStrings(@EnrollNumbers,',')) as a on dbo.tblEnroll.EnrollNumber = cast(a.item as int)
End
GO

