create or Alter Procedure [dbo].sp_Gharardad_SelectRowByPersonIdAndDate
	@personId int,
	@dateStartM datetime,
	@dateFinishM datetime
As
Begin
	SELECT	*
	FROM	dbo.Gharardad 
	Where	personId=@personId and 
			(
				(DateStartM <= @dateStartM and DateFinishM >= @dateFinishM) or
				(DateFinishM >= @dateStartM and DateFinishM <= @dateFinishM) or
				(DateStartM >= @dateStartM and DateStartM <= @dateFinishM)
			)			 
End
go

