Create or ALTER   PROCEDURE [dbo].[sp_HardwareCodeCus_SelectAllModel]	
AS
BEGIN
		delete Att_BioDeviceRelation
	from Att_BioDeviceRelation
	inner join
	(
		select HardwareCode,DeviceGuid
		from Att_BioDeviceRelation

		except

		select HardwareCode,DeviceInfo.Guid
		from HardwareCodeCus
		inner join DeviceInfo on DeviceInfo.ID=HardwareCodeCus.DeviceID
		where HardwareCodeCus.HardwareCode>0
	) as Exist on Exist.DeviceGuid=Att_BioDeviceRelation.DeviceGuid and Exist.HardwareCode=Att_BioDeviceRelation.HardwareCode

	select    DeviceInfo.Model As DeviceType
			, DeviceInfo.Guid As DeviceGuid
			, Person.GUID As PersonGuid
			, Person.FullName As PersonName
			, Inserted.HardwareCode
	from
	(
		select    HardwareCode
				, DeviceInfo.Guid
		from HardwareCodeCus
		inner join DeviceInfo on DeviceInfo.ID=HardwareCodeCus.DeviceID
		where HardwareCodeCus.HardwareCode>0

		except

		select    HardwareCode
				, DeviceGuid
		from Att_BioDeviceRelation
	)as Inserted
	inner join HardwareCodeCus on HardwareCodeCus.HardwareCode=Inserted.HardwareCode
	inner join DeviceInfo on DeviceInfo.ID=HardwareCodeCus.DeviceID
	inner join Person on Person.ID=HardwareCodeCus.PersonID
END
GO
-- ==========================================================================================
CREATE or Alter PROCEDURE sp_HardwareCodeCus_CopyData
	@SourceDeviceGuid uniqueidentifier,
	@DestinationDeviceGuid uniqueidentifier
AS
BEGIN
	declare @DestinationDeviceId int
	declare @SourceDeviceId int

	select @SourceDeviceId = Id
	from DeviceInfo
	where Guid = @SourceDeviceGuid

	select @DestinationDeviceId = Id
	from DeviceInfo
	where Guid = @DestinationDeviceGuid

	if(ISNULL(@SourceDeviceId,0)<=0 or ISNULL(@DestinationDeviceId,0)<=0)
		return

	delete from HardwareCodeCus
	where DeviceID=@DestinationDeviceId

	INSERT INTO [dbo].[HardwareCodeCus]
           ([PersonID]
           ,[DeviceID]
           ,[HardwareCode]
           ,[DateInserted]
           ,[Guid])
	select    PersonID
			, @DestinationDeviceId
			, HardwareCode
			, GETDATE()
			, NEWID()
	from HardwareCodeCus
	where DeviceID = @SourceDeviceId
END
GO
-- ==========================================================================================
CREATE or Alter PROCEDURE sp_Att_BioWriteDevice_FetchNextForSend
	@DeviceGuid uniqueidentifier
AS
BEGIN
	declare @Date datetime
	set @Date=dateadd(mi,10,getdate())

	declare @Temp table 
	(
		BioGuid uniqueidentifier,
		DeviceGuid uniqueidentifier
	)

	insert into @Temp
	select top(1) BioGuid,DeviceGuid
	from Att_BioWriteDevice
	where DeviceGuid=@DeviceGuid
		  and NextTry<=@Date
	Order by NextTry

	update Att_BioWriteDevice
	set   TryCount=TryCount+1
		, NextTry=@Date
	from Att_BioWriteDevice
	inner join @Temp as T on t.BioGuid=Att_BioWriteDevice.BioGuid and t.DeviceGuid=Att_BioWriteDevice.DeviceGuid

	select Att_BioWriteDevice.*
	from Att_BioWriteDevice
	inner join @Temp as T on t.BioGuid=Att_BioWriteDevice.BioGuid and t.DeviceGuid=Att_BioWriteDevice.DeviceGuid
	order by InsertedDateM
END
GO
-- ==========================================================================================
CREATE or Alter PROCEDURE sp_Att_BioWriteDevice_SelectAll
AS
BEGIN
	select    Att_BioWriteDevice.*
			, ISNULL(DeviceInfo.DeviceName,'') As DeviceName
			, ISNULL(Person.FullName,'') As PersonName
			, ISNULL(Att_Biometric.DeviceGroup,0) as DeviceGroup
			, ISNULL(Att_Biometric.FingerPrintCount,0) as FingerPrintCount
			, ISNULL(Att_Biometric.HasPalm,'false') as HasPalm
			, ISNULL(Att_Biometric.HasPassword,'false') as HasPassword
			, ISNULL(Att_Biometric.HasFace,'false') as HasFace
			, ISNULL(Att_Biometric.HasCard,'false') as HasCard
	from Att_BioWriteDevice
	inner join DeviceInfo on Att_BioWriteDevice.DeviceGuid=DeviceInfo.Guid
	left outer join Att_Biometric on Att_Biometric.Guid=Att_BioWriteDevice.BioGuid
	left outer join Person on Person.Guid=Att_Biometric.PersonGuid
END
GO
-- ==========================================================================================
CREATE Or Alter PROCEDURE sp_Att_BioWriteDeviceLog_SelectAll
	  @DeviceGuid uniqueidentifier = null
	, @PersonGuid uniqueidentifier = null
	, @UserGuid uniqueidentifier = null
	, @DateFrom datetime = null
	, @DateTo datetime = null
	, @HardwareCode int = null
AS
BEGIN
	select    Att_BioWriteDeviceLog.*
			, ISNULL(DeviceInfo.DeviceName,'') as DeviceName
			, ISNULL(Person.FullName,'') as PersonName
	from Att_BioWriteDeviceLog
	inner join DeviceInfo on DeviceInfo.Guid=Att_BioWriteDeviceLog.DeviceGuid
	left outer join Att_Biometric on Att_Biometric.Guid=Att_BioWriteDeviceLog.BioGuid
	left outer join Person on Person.Guid=Att_Biometric.PersonGuid
	where (ISNULL(@DeviceGuid,'00000000-0000-0000-0000-000000000000')='00000000-0000-0000-0000-000000000000' or Att_BioWriteDeviceLog.DeviceGuid=@DeviceGuid) and
		  (ISNULL(@PersonGuid,'00000000-0000-0000-0000-000000000000')='00000000-0000-0000-0000-000000000000' or Person.Guid=@PersonGuid) and
		  (ISNULL(@UserGuid,'00000000-0000-0000-0000-000000000000')='00000000-0000-0000-0000-000000000000' or Att_BioWriteDeviceLog.UserGuid=@UserGuid) and
		  (@DateFrom is null or Att_BioWriteDeviceLog.DateM>=@DateFrom) and
		  (@DateTo is null or Att_BioWriteDeviceLog.DateM<=@DateTo) and
		  (ISNULL(@HardwareCode,0)=0 or Att_BioWriteDeviceLog.HardwareCode=@HardwareCode)
END
GO
-- ==========================================================================================
Create or Alter   PROCEDURE [dbo].[sp_Att_BioDeviceRelation_SelectAll]
	  @DeviceGuid uniqueidentifier
AS
BEGIN
	select    Att_BioDeviceRelation.*
			, ISNULL(DeviceInfo.DeviceName,'') As DeviceName
			, ISNULL(Person.FullName,'') As PersonName
			, ISNULL(Att_Biometric.FingerPrintCount,0) as FingerPrintCount
			, ISNULL(Att_Biometric.HasPalm,'false') as HasPalm
			, ISNULL(Att_Biometric.HasFace,'false') as HasFace
			, ISNULL(Att_Biometric.HasCard,'false') as HasCard
			, ISNULL(Att_Biometric.HasPassword,'false') as HasPassword
	from Att_BioDeviceRelation
	inner join DeviceInfo on DeviceInfo.Guid=Att_BioDeviceRelation.DeviceGuid
	left outer join Att_Biometric on Att_Biometric.Guid=Att_BioDeviceRelation.BioGuid
	left outer join Person on Person.Guid=Att_Biometric.PersonGuid
	where Att_BioDeviceRelation.DeviceGuid=@DeviceGuid
END
Go
